-- OTSI VIE MySQL 8.4 schema v2 — ALL-IN-ONE (migrations 001-014). EMPTY server only.

-- ===== 001_foundation_identity_storage.sql =====
-- =====================================================================================
-- OTSI VIE — MySQL 8.4 LTS schema `otsi_owner_vie`  (Blueprint v2, UI-aligned)
-- Migration 001 — Foundation: tenancy, identity, access, preferences, notifications, object storage
-- Conventions (apply to every migration):
--   * IDs: UUIDv7 generated by the API/worker, stored CHAR(36) CHARACTER SET ascii COLLATE ascii_bin (36 bytes; time-ordered => append-friendly B-tree).
--   * Every tenant-owned table carries organization_id and UNIQUE(organization_id,id); children reference parents
--     with COMPOSITE foreign keys (organization_id, parent_id) so a cross-tenant reference is impossible in the DB.
--   * Times: DATETIME(6) UTC. Media time: BIGINT microseconds (`*_pts_us`). Money: BIGINT minor units.
--   * Evidence: every analytical value carries ENUM('DETECTED','INFERRED','CONFIRMED','NOT_MEASURED'); NOT_MEASURED => value NULL (CHECK enforced).
--   * Optimistic concurrency: `row_version` incremented by triggers (migration 011); APIs use ETag/If-Match.
-- =====================================================================================
CREATE DATABASE IF NOT EXISTS `otsi_owner_vie` CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE `otsi_owner_vie`;

CREATE TABLE organizations (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  name              VARCHAR(200) NOT NULL,
  slug              VARCHAR(100) CHARACTER SET ascii NOT NULL,
  org_type          ENUM('CLUB','AGENCY','ANALYST_STUDIO','FEDERATION','MEDIA','INTERNAL') NOT NULL DEFAULT 'ANALYST_STUDIO',
  country_code      CHAR(2) CHARACTER SET ascii NULL,
  default_timezone  VARCHAR(64) NOT NULL DEFAULT 'UTC',
  status            ENUM('ACTIVE','SUSPENDED','CLOSED') NOT NULL DEFAULT 'ACTIVE',
  settings          JSON NOT NULL DEFAULT (JSON_OBJECT()),
  created_at        DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at        DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  row_version       BIGINT UNSIGNED NOT NULL DEFAULT 1,
  PRIMARY KEY (id),
  UNIQUE KEY uq_organizations_slug (slug),
  CONSTRAINT ck_organizations_slug CHECK (REGEXP_LIKE(slug, '^[a-z0-9][a-z0-9-]{1,98}[a-z0-9]$'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='Tenant. Header "OTSI VIE" sub-label = organizations.name';

CREATE TABLE users (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  external_subject  VARCHAR(255) CHARACTER SET ascii NOT NULL COMMENT 'OIDC sub; no passwords stored here',
  email             VARCHAR(320) NOT NULL,
  email_verified    BOOLEAN NOT NULL DEFAULT FALSE,
  display_name      VARCHAR(120) NOT NULL,
  initials          VARCHAR(3) NOT NULL COMMENT 'Avatar text: header "O", collaborator chips "JD","SK","MC"',
  avatar_color_hex  CHAR(7) CHARACTER SET ascii NULL,
  avatar_asset_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  locale            VARCHAR(16) NOT NULL DEFAULT 'en',
  status            ENUM('ACTIVE','DISABLED','DELETED') NOT NULL DEFAULT 'ACTIVE',
  last_seen_at      DATETIME(6) NULL,
  created_at        DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at        DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  PRIMARY KEY (id),
  UNIQUE KEY uq_users_subject (external_subject),
  UNIQUE KEY uq_users_email (email),
  CONSTRAINT ck_users_color CHECK (avatar_color_hex IS NULL OR REGEXP_LIKE(avatar_color_hex, '^#[0-9a-fA-F]{6}$'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE memberships (
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  user_id           CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  role              ENUM('OWNER','ADMIN','ANALYST','EDITOR','SCOUT','VIEWER') NOT NULL,
  job_title         VARCHAR(80) NULL COMMENT 'Shown under collaborator names: Analyst / Scout / Video Editor',
  status            ENUM('INVITED','ACTIVE','SUSPENDED','REMOVED') NOT NULL DEFAULT 'ACTIVE',
  joined_at         DATETIME(6) NULL,
  created_at        DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at        DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  PRIMARY KEY (organization_id, user_id),
  KEY ix_memberships_user (user_id, status),
  CONSTRAINT fk_memberships_org  FOREIGN KEY (organization_id) REFERENCES organizations(id) ON DELETE CASCADE,
  CONSTRAINT fk_memberships_user FOREIGN KEY (user_id) REFERENCES users(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='Header "Owner" label = role of current membership (or display_name per product decision)';

CREATE TABLE invitations (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  email             VARCHAR(320) NOT NULL,
  role              ENUM('ADMIN','ANALYST','EDITOR','SCOUT','VIEWER') NOT NULL,
  token_hash        CHAR(64) CHARACTER SET ascii NOT NULL,
  invited_by        CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  expires_at        DATETIME(6) NOT NULL,
  accepted_at       DATETIME(6) NULL,
  revoked_at        DATETIME(6) NULL,
  created_at        DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (id),
  UNIQUE KEY uq_invitations_token (token_hash),
  KEY ix_invitations_org_email (organization_id, email),
  CONSTRAINT fk_invitations_org FOREIGN KEY (organization_id) REFERENCES organizations(id) ON DELETE CASCADE,
  CONSTRAINT fk_invitations_by  FOREIGN KEY (invited_by) REFERENCES users(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE user_preferences (
  user_id           CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  display_mode      ENUM('QHD','FHD','AUTO') NOT NULL DEFAULT 'QHD' COMMENT 'Header "QHD" badge',
  theme             ENUM('DARK','LIGHT','SYSTEM') NOT NULL DEFAULT 'DARK',
  ui_state          JSON NOT NULL DEFAULT (JSON_OBJECT()) COMMENT 'Last tabs/toggles per page (e.g. overlay toggles, auto-scroll)',
  updated_at        DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  PRIMARY KEY (user_id, organization_id),
  CONSTRAINT fk_userprefs_member FOREIGN KEY (organization_id, user_id) REFERENCES memberships(organization_id, user_id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE notifications (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  user_id           CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  kind              VARCHAR(64) CHARACTER SET ascii NOT NULL COMMENT 'JOB_SUCCEEDED, RENDER_READY, DELIVERY_SENT, REVIEW_REQUIRED, MENTION ...',
  entity_type       VARCHAR(48) CHARACTER SET ascii NOT NULL,
  entity_id         CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  title             VARCHAR(200) NOT NULL,
  body              VARCHAR(500) NULL,
  read_at           DATETIME(6) NULL,
  created_at        DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (id),
  KEY ix_notifications_inbox (organization_id, user_id, read_at, created_at),
  CONSTRAINT fk_notifications_member FOREIGN KEY (organization_id, user_id) REFERENCES memberships(organization_id, user_id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

-- Object storage registry. Bytes live in S3-compatible storage; MySQL stores metadata, checksums and lineage.
CREATE TABLE storage_buckets (
  id                SMALLINT UNSIGNED NOT NULL AUTO_INCREMENT,
  name              VARCHAR(63) CHARACTER SET ascii NOT NULL,
  region            VARCHAR(32) CHARACTER SET ascii NOT NULL,
  purpose           ENUM('SOURCE','DERIVED','RENDERS','REPORTS','CV_ARTIFACTS','BRANDING','QUARANTINE') NOT NULL,
  kms_key_ref       VARCHAR(255) NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_storage_buckets_name (name)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE assets (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  project_id        CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  kind              ENUM('SOURCE_VIDEO','PROXY_VIDEO','HLS_PACKAGE','THUMBNAIL','POSTER','SPRITE_SHEET','WAVEFORM',
                         'TRACKS_PARQUET','DETECTIONS_PARQUET','EVENTS_PARQUET','HEATMAP_IMAGE','HEATMAP_GRID',
                         'CLIP','REEL_RENDER','PREVIEW_RENDER','REPORT_PDF','REPORT_CSV','REPORT_PNG','RENDER_MANIFEST',
                         'CAPTIONS_VTT','AUDIO_TRACK','LOGO','FONT','GRAPHIC_TEMPLATE','RIGHTS_EVIDENCE','OTHER') NOT NULL,
  bucket_id         SMALLINT UNSIGNED NOT NULL,
  object_key        VARCHAR(1024) CHARACTER SET ascii NOT NULL,
  object_key_hash   BINARY(32) AS (UNHEX(SHA2(object_key, 256))) STORED COMMENT 'Fixed-width uniqueness for long keys',
  original_filename VARCHAR(512) NULL COMMENT 'Upload "File Name"',
  byte_size         BIGINT UNSIGNED NULL COMMENT 'Upload "File Size"',
  sha256            CHAR(64) CHARACTER SET ascii NULL,
  mime_type         VARCHAR(127) CHARACTER SET ascii NULL,
  source_asset_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'Derivation lineage',
  storage_state     ENUM('PENDING','AVAILABLE','QUARANTINED','DELETING','DELETED') NOT NULL DEFAULT 'PENDING',
  retention_until   DATETIME(6) NULL,
  legal_hold        BOOLEAN NOT NULL DEFAULT FALSE,
  metadata          JSON NOT NULL DEFAULT (JSON_OBJECT()),
  created_by        CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  created_at        DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (id),
  UNIQUE KEY uq_assets_org_id (organization_id, id),
  UNIQUE KEY uq_assets_location (bucket_id, object_key_hash),
  KEY ix_assets_org_kind (organization_id, kind, created_at),
  KEY ix_assets_source (organization_id, source_asset_id),
  CONSTRAINT fk_assets_org    FOREIGN KEY (organization_id) REFERENCES organizations(id),
  CONSTRAINT fk_assets_bucket FOREIGN KEY (bucket_id) REFERENCES storage_buckets(id),
  CONSTRAINT fk_assets_source FOREIGN KEY (organization_id, source_asset_id) REFERENCES assets(organization_id, id),
  CONSTRAINT fk_assets_user   FOREIGN KEY (created_by) REFERENCES users(id),
  CONSTRAINT ck_assets_sha    CHECK (sha256 IS NULL OR REGEXP_LIKE(sha256, '^[0-9a-f]{64}$'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

ALTER TABLE users ADD CONSTRAINT fk_users_avatar FOREIGN KEY (avatar_asset_id) REFERENCES assets(id);

-- Global (non-tenant) assets such as licensed music, OTSI brand kit and crests are owned by the platform org
-- `00000000-0000-7000-8000-000000000000` seeded in migration 013.

-- ===== 002_reference_registry_matches.sql =====
-- Migration 002 — Reference data, canonical player registry (OTSI Player IDs), clubs, competitions, matches, rosters
USE `otsi_owner_vie`;

CREATE TABLE countries (
  code              CHAR(2) CHARACTER SET ascii NOT NULL COMMENT 'ISO 3166-1 alpha-2',
  code3             CHAR(3) CHARACTER SET ascii NOT NULL,
  name              VARCHAR(100) NOT NULL,
  flag_asset_id     CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'Flag tile shown beside nationality (06, 08, 04)',
  PRIMARY KEY (code),
  UNIQUE KEY uq_countries_code3 (code3),
  CONSTRAINT fk_countries_flag FOREIGN KEY (flag_asset_id) REFERENCES assets(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE competitions (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  owner_organization_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'NULL = platform catalogue; else tenant-private competition',
  name              VARCHAR(150) NOT NULL COMMENT 'e.g. shown in Match card, Competition select, Library filter',
  short_name        VARCHAR(30) NULL COMMENT 'e.g. chip "UCL"',
  competition_type  ENUM('LEAGUE','CUP','INTERNATIONAL','FRIENDLY','YOUTH','TRAINING','OTHER') NOT NULL,
  country_code      CHAR(2) CHARACTER SET ascii NULL,
  logo_asset_id     CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  logo_license_ref  VARCHAR(255) NULL COMMENT 'Required before any logo is rendered (no implied endorsement)',
  external_ids      JSON NOT NULL DEFAULT (JSON_OBJECT()),
  created_at        DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  owner_key         CHAR(36) CHARACTER SET ascii COLLATE ascii_bin AS (COALESCE(owner_organization_id, 'GLOBAL')) STORED COMMENT 'NULL-safe uniqueness',
  PRIMARY KEY (id),
  UNIQUE KEY uq_competitions_owner_name (owner_key, name),
  CONSTRAINT fk_competitions_owner   FOREIGN KEY (owner_organization_id) REFERENCES organizations(id),
  CONSTRAINT fk_competitions_country FOREIGN KEY (country_code) REFERENCES countries(code),
  CONSTRAINT fk_competitions_logo    FOREIGN KEY (logo_asset_id) REFERENCES assets(id),
  CONSTRAINT ck_competitions_logo_license CHECK (logo_asset_id IS NULL OR logo_license_ref IS NOT NULL)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE seasons (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  competition_id    CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  label             VARCHAR(20) NOT NULL COMMENT 'Season select value, e.g. 2024/2025',
  starts_on         DATE NOT NULL,
  ends_on           DATE NOT NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_seasons_comp_label (competition_id, label),
  CONSTRAINT fk_seasons_comp FOREIGN KEY (competition_id) REFERENCES competitions(id),
  CONSTRAINT ck_seasons_range CHECK (ends_on > starts_on)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE clubs (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  owner_organization_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  canonical_name    VARCHAR(150) NOT NULL COMMENT 'e.g. team name lines in match cards',
  short_name        VARCHAR(50) NULL,
  code3             CHAR(3) CHARACTER SET ascii NULL COMMENT 'Scorebug / badges e.g. MCI, RMA',
  country_code      CHAR(2) CHARACTER SET ascii NULL,
  crest_asset_id    CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  crest_license_ref VARCHAR(255) NULL,
  primary_color_hex CHAR(7) CHARACTER SET ascii NULL COMMENT 'Crest circle fallback colour',
  external_ids      JSON NOT NULL DEFAULT (JSON_OBJECT()),
  created_at        DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (id),
  KEY ix_clubs_name (canonical_name),
  CONSTRAINT fk_clubs_owner   FOREIGN KEY (owner_organization_id) REFERENCES organizations(id),
  CONSTRAINT fk_clubs_country FOREIGN KEY (country_code) REFERENCES countries(code),
  CONSTRAINT fk_clubs_crest   FOREIGN KEY (crest_asset_id) REFERENCES assets(id),
  CONSTRAINT ck_clubs_crest_license CHECK (crest_asset_id IS NULL OR crest_license_ref IS NOT NULL)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE club_aliases (
  club_id           CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  alias             VARCHAR(150) NOT NULL,
  source            VARCHAR(50) NOT NULL DEFAULT 'MANUAL',
  PRIMARY KEY (club_id, alias),
  KEY ix_club_aliases_alias (alias),
  CONSTRAINT fk_club_aliases_club FOREIGN KEY (club_id) REFERENCES clubs(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE club_kits (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  club_id           CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  season_label      VARCHAR(20) NULL,
  kit_type          ENUM('HOME','AWAY','THIRD','GK','OTHER') NOT NULL,
  colour_name       VARCHAR(40) NULL COMMENT 'Team Identification tile: "(Blue)" / "(White)"',
  shirt_color_hex   CHAR(7) CHARACTER SET ascii NOT NULL,
  shorts_color_hex  CHAR(7) CHARACTER SET ascii NULL,
  PRIMARY KEY (id),
  KEY ix_club_kits_club (club_id, season_label),
  CONSTRAINT fk_club_kits_club FOREIGN KEY (club_id) REFERENCES clubs(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE positions (
  code              VARCHAR(4) CHARACTER SET ascii NOT NULL COMMENT 'GK, CB, LB, RB, DM, MC, AM, LW, RW, CF ...',
  label             VARCHAR(40) NOT NULL COMMENT 'Midfielder / Attacking Midfielder ...',
  line              ENUM('GOALKEEPER','DEFENDER','MIDFIELDER','FORWARD') NOT NULL,
  sort_order        TINYINT UNSIGNED NOT NULL,
  PRIMARY KEY (code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

-- Canonical OTSI Player IDs: OTSI-CCC-YYYY-NNNNNN, allocated server-side ONLY via sp_allocate_otsi_player_id (migration 011).
CREATE TABLE otsi_player_id_sequences (
  country_code      CHAR(3) CHARACTER SET ascii NOT NULL,
  year_part         SMALLINT UNSIGNED NOT NULL,
  next_value        INT UNSIGNED NOT NULL DEFAULT 1,
  PRIMARY KEY (country_code, year_part),
  CONSTRAINT ck_otsi_seq CHECK (next_value BETWEEN 1 AND 999999)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE players (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  owner_organization_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'NULL = platform registry; else tenant-private (e.g. academy player)',
  canonical_otsi_id VARCHAR(20) CHARACTER SET ascii NULL,
  canonical_state   ENUM('PENDING','VERIFIED','MERGED','RETIRED') NOT NULL DEFAULT 'PENDING',
  merged_into_player_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  display_name      VARCHAR(120) NOT NULL COMMENT 'Hero name, list names',
  short_name        VARCHAR(60) NULL COMMENT 'Timeline lane labels e.g. "K. De Bruyne"',
  shirt_name        VARCHAR(30) NULL COMMENT 'Formation board labels (uppercase surname)',
  given_name        VARCHAR(80) NULL,
  family_name       VARCHAR(80) NULL,
  birth_date        DATE NULL COMMENT 'Age is DERIVED, never stored',
  nationality_code  CHAR(2) CHARACTER SET ascii NULL,
  second_nationality_code CHAR(2) CHARACTER SET ascii NULL,
  height_cm         SMALLINT UNSIGNED NULL,
  weight_kg         DECIMAL(5,1) NULL,
  preferred_foot    ENUM('LEFT','RIGHT','BOTH','UNKNOWN') NOT NULL DEFAULT 'UNKNOWN',
  primary_position_code VARCHAR(4) CHARACTER SET ascii NULL,
  photo_asset_id    CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  photo_license_ref VARCHAR(255) NULL,
  bio_evidence_state ENUM('DETECTED','INFERRED','CONFIRMED','NOT_MEASURED') NOT NULL DEFAULT 'NOT_MEASURED' COMMENT 'Provenance of height/weight/birth date',
  external_ids      JSON NOT NULL DEFAULT (JSON_OBJECT()),
  created_at        DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at        DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  row_version       BIGINT UNSIGNED NOT NULL DEFAULT 1,
  PRIMARY KEY (id),
  UNIQUE KEY uq_players_otsi_id (canonical_otsi_id),
  KEY ix_players_name (display_name),
  FULLTEXT KEY ft_players_names (display_name, short_name, family_name),
  CONSTRAINT fk_players_owner    FOREIGN KEY (owner_organization_id) REFERENCES organizations(id),
  CONSTRAINT fk_players_merged   FOREIGN KEY (merged_into_player_id) REFERENCES players(id),
  CONSTRAINT fk_players_nat      FOREIGN KEY (nationality_code) REFERENCES countries(code),
  CONSTRAINT fk_players_nat2     FOREIGN KEY (second_nationality_code) REFERENCES countries(code),
  CONSTRAINT fk_players_position FOREIGN KEY (primary_position_code) REFERENCES positions(code),
  CONSTRAINT fk_players_photo    FOREIGN KEY (photo_asset_id) REFERENCES assets(id),
  CONSTRAINT ck_players_otsi_format CHECK (canonical_otsi_id IS NULL OR REGEXP_LIKE(canonical_otsi_id, '^OTSI-[A-Z]{3}-[0-9]{4}-[0-9]{6}$', 'c')),
  CONSTRAINT ck_players_verified_has_id CHECK (canonical_state <> 'VERIFIED' OR canonical_otsi_id IS NOT NULL),
  CONSTRAINT ck_players_merged CHECK ((canonical_state = 'MERGED') = (merged_into_player_id IS NOT NULL)),
  CONSTRAINT ck_players_height CHECK (height_cm IS NULL OR height_cm BETWEEN 120 AND 230),
  CONSTRAINT ck_players_weight CHECK (weight_kg IS NULL OR weight_kg BETWEEN 30 AND 150),
  CONSTRAINT ck_players_photo_license CHECK (photo_asset_id IS NULL OR photo_license_ref IS NOT NULL)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE player_positions (
  player_id         CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  position_code     VARCHAR(4) CHARACTER SET ascii NOT NULL,
  is_primary        BOOLEAN NOT NULL DEFAULT FALSE,
  sort_order        TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT 'Hero chips MC / AM / RW order',
  PRIMARY KEY (player_id, position_code),
  CONSTRAINT fk_player_positions_player FOREIGN KEY (player_id) REFERENCES players(id) ON DELETE CASCADE,
  CONSTRAINT fk_player_positions_pos    FOREIGN KEY (position_code) REFERENCES positions(code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE player_club_spells (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  player_id         CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  club_id           CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  squad_number      TINYINT UNSIGNED NULL COMMENT 'Jersey badge (never used to infer identity)',
  valid_from        DATE NOT NULL,
  valid_to          DATE NULL,
  source            VARCHAR(80) NOT NULL DEFAULT 'MANUAL',
  verified          BOOLEAN NOT NULL DEFAULT FALSE,
  PRIMARY KEY (id),
  KEY ix_spells_player (player_id, valid_from),
  KEY ix_spells_club (club_id, valid_from),
  CONSTRAINT fk_spells_player FOREIGN KEY (player_id) REFERENCES players(id) ON DELETE CASCADE,
  CONSTRAINT fk_spells_club   FOREIGN KEY (club_id) REFERENCES clubs(id),
  CONSTRAINT ck_spells_number CHECK (squad_number IS NULL OR squad_number <= 99),
  CONSTRAINT ck_spells_range  CHECK (valid_to IS NULL OR valid_to >= valid_from)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE matches (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  competition_id    CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  season_id         CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  match_type        ENUM('MATCH','TRAINING','FRIENDLY','OTHER') NOT NULL DEFAULT 'MATCH' COMMENT 'Recent upload subtitle "Training"',
  title_override    VARCHAR(200) NULL COMMENT 'Used when not a fixture (e.g. "Training Session")',
  kickoff_at        DATETIME(6) NULL COMMENT 'Match card date "Tue, 16 Apr 2024" (formatted client-side in org timezone)',
  venue             VARCHAR(150) NULL,
  home_club_id      CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  away_club_id      CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  home_score        TINYINT UNSIGNED NULL,
  away_score        TINYINT UNSIGNED NULL,
  score_state       ENUM('DETECTED','INFERRED','CONFIRMED','NOT_MEASURED') NOT NULL DEFAULT 'NOT_MEASURED',
  metadata_state    ENUM('DETECTED','INFERRED','CONFIRMED','NOT_MEASURED') NOT NULL DEFAULT 'INFERRED',
  match_status      ENUM('SCHEDULED','PLAYED','ABANDONED','UNKNOWN') NOT NULL DEFAULT 'UNKNOWN',
  created_by        CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  created_at        DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at        DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  row_version       BIGINT UNSIGNED NOT NULL DEFAULT 1,
  PRIMARY KEY (id),
  UNIQUE KEY uq_matches_org_id (organization_id, id),
  KEY ix_matches_org_kickoff (organization_id, kickoff_at),
  KEY ix_matches_org_comp (organization_id, competition_id, season_id),
  KEY ix_matches_clubs (home_club_id, away_club_id),
  CONSTRAINT fk_matches_org    FOREIGN KEY (organization_id) REFERENCES organizations(id),
  CONSTRAINT fk_matches_comp   FOREIGN KEY (competition_id) REFERENCES competitions(id),
  CONSTRAINT fk_matches_season FOREIGN KEY (season_id) REFERENCES seasons(id),
  CONSTRAINT fk_matches_home   FOREIGN KEY (home_club_id) REFERENCES clubs(id),
  CONSTRAINT fk_matches_away   FOREIGN KEY (away_club_id) REFERENCES clubs(id),
  CONSTRAINT fk_matches_user   FOREIGN KEY (created_by) REFERENCES users(id),
  CONSTRAINT ck_matches_distinct_clubs CHECK (home_club_id IS NULL OR away_club_id IS NULL OR home_club_id <> away_club_id),
  CONSTRAINT ck_matches_score CHECK ((home_score IS NULL) = (away_score IS NULL)),
  CONSTRAINT ck_matches_score_state CHECK (score_state <> 'NOT_MEASURED' OR home_score IS NULL)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE match_periods (
  match_id          CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  period            ENUM('FIRST_HALF','SECOND_HALF','ET_FIRST','ET_SECOND','PENALTIES') NOT NULL COMMENT 'Time Range radio: 1st Half / 2nd Half',
  clock_start_ms    INT UNSIGNED NOT NULL COMMENT 'Match clock at period start (0, 2700000 ...)',
  added_time_ms     INT UNSIGNED NULL,
  PRIMARY KEY (match_id, period),
  CONSTRAINT fk_match_periods_match FOREIGN KEY (organization_id, match_id) REFERENCES matches(organization_id, id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE match_rosters (
  match_id          CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  player_id         CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  club_id           CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  side              ENUM('HOME','AWAY') NOT NULL,
  jersey_number     TINYINT UNSIGNED NULL,
  position_code     VARCHAR(4) CHARACTER SET ascii NULL,
  is_starter        BOOLEAN NOT NULL DEFAULT FALSE,
  minutes_on        SMALLINT UNSIGNED NULL,
  minutes_off       SMALLINT UNSIGNED NULL,
  roster_state      ENUM('DETECTED','INFERRED','CONFIRMED','NOT_MEASURED') NOT NULL DEFAULT 'INFERRED',
  source_uri        VARCHAR(1024) NULL,
  PRIMARY KEY (match_id, player_id),
  UNIQUE KEY uq_rosters_number (match_id, side, jersey_number),
  KEY ix_rosters_player (player_id),
  KEY ix_rosters_org (organization_id, match_id, side),
  CONSTRAINT fk_rosters_match  FOREIGN KEY (organization_id, match_id) REFERENCES matches(organization_id, id) ON DELETE CASCADE,
  CONSTRAINT fk_rosters_player FOREIGN KEY (player_id) REFERENCES players(id),
  CONSTRAINT fk_rosters_club   FOREIGN KEY (club_id) REFERENCES clubs(id),
  CONSTRAINT fk_rosters_pos    FOREIGN KEY (position_code) REFERENCES positions(code),
  CONSTRAINT ck_rosters_number CHECK (jersey_number IS NULL OR jersey_number <= 99)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='Team Filter counts (All Players 22 / team 11) = COUNT(*) per side';

CREATE TABLE partner_brands (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  name              VARCHAR(120) NOT NULL,
  logo_asset_id     CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  license_ref       VARCHAR(255) NOT NULL COMMENT 'Contract / written permission reference. No row => nothing shown',
  license_valid_until DATE NULL,
  display_order     SMALLINT UNSIGNED NOT NULL DEFAULT 0,
  is_active         BOOLEAN NOT NULL DEFAULT TRUE,
  PRIMARY KEY (id),
  CONSTRAINT fk_partner_brands_logo FOREIGN KEY (logo_asset_id) REFERENCES assets(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='01 Home "TRUSTED PARTNERS" strip — only licensed marks';

-- ===== 003_projects_library_collaboration.sql =====
-- Migration 003 — Projects, folders, tags, unified Library catalogue (09), saved searches, bookmarks, comments
USE `otsi_owner_vie`;

CREATE TABLE projects (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  name              VARCHAR(200) NOT NULL,
  description       TEXT NULL,
  primary_match_id  CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  status            ENUM('ACTIVE','ARCHIVED') NOT NULL DEFAULT 'ACTIVE',
  created_by        CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  created_at        DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at        DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  row_version       BIGINT UNSIGNED NOT NULL DEFAULT 1,
  PRIMARY KEY (id),
  UNIQUE KEY uq_projects_org_id (organization_id, id),
  KEY ix_projects_org_updated (organization_id, status, updated_at),
  CONSTRAINT fk_projects_org   FOREIGN KEY (organization_id) REFERENCES organizations(id),
  CONSTRAINT fk_projects_match FOREIGN KEY (organization_id, primary_match_id) REFERENCES matches(organization_id, id),
  CONSTRAINT fk_projects_user  FOREIGN KEY (organization_id, created_by) REFERENCES memberships(organization_id, user_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

ALTER TABLE assets ADD CONSTRAINT fk_assets_project FOREIGN KEY (organization_id, project_id) REFERENCES projects(organization_id, id);

CREATE TABLE project_members (
  project_id        CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  user_id           CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  permission        ENUM('READ','COMMENT','EDIT','REVIEW','ADMIN') NOT NULL,
  granted_by        CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  granted_at        DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (project_id, user_id),
  KEY ix_project_members_user (organization_id, user_id),
  CONSTRAINT fk_pm_project FOREIGN KEY (organization_id, project_id) REFERENCES projects(organization_id, id) ON DELETE CASCADE,
  CONSTRAINT fk_pm_member  FOREIGN KEY (organization_id, user_id) REFERENCES memberships(organization_id, user_id) ON DELETE CASCADE,
  CONSTRAINT fk_pm_granter FOREIGN KEY (granted_by) REFERENCES users(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE folders (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  parent_folder_id  CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  name              VARCHAR(150) NOT NULL COMMENT 'Media Bin breadcrumb segments / Library "Folder" rows',
  folder_kind       ENUM('GENERAL','SCOUTING_DOSSIER','MEDIA_BIN','DELIVERY_PACK') NOT NULL DEFAULT 'GENERAL',
  path_cache        VARCHAR(2000) NULL COMMENT 'Materialised "/Folders/Team/Player/Season" for breadcrumb',
  depth             TINYINT UNSIGNED NOT NULL DEFAULT 0,
  created_by        CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  created_at        DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at        DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  PRIMARY KEY (id),
  UNIQUE KEY uq_folders_org_id (organization_id, id),
  UNIQUE KEY uq_folders_sibling_name (organization_id, parent_folder_id, name),
  CONSTRAINT fk_folders_org    FOREIGN KEY (organization_id) REFERENCES organizations(id),
  CONSTRAINT fk_folders_parent FOREIGN KEY (organization_id, parent_folder_id) REFERENCES folders(organization_id, id),
  CONSTRAINT fk_folders_user   FOREIGN KEY (created_by) REFERENCES users(id),
  CONSTRAINT ck_folders_depth  CHECK (depth <= 12)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE tags (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  label             VARCHAR(60) NOT NULL COMMENT 'Chips: Progressive, Passing, UCL, Build-up ...',
  normalized_label  VARCHAR(60) AS (LOWER(TRIM(label))) STORED,
  tag_kind          ENUM('FREE','EVENT','PLAYER','COMPETITION','SYSTEM') NOT NULL DEFAULT 'FREE',
  color_hex         CHAR(7) CHARACTER SET ascii NULL,
  created_at        DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (id),
  UNIQUE KEY uq_tags_org_id (organization_id, id),
  UNIQUE KEY uq_tags_org_label (organization_id, normalized_label),
  CONSTRAINT fk_tags_org FOREIGN KEY (organization_id) REFERENCES organizations(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

-- Unified catalogue powering Library tabs, counts, table rows, search and the Selected Item panel.
-- Domain tables (reels, reports, matches, folders, render outputs, templates, clips) are the source of truth;
-- library_items is written in the SAME transaction as the domain write (or by outbox projector) — never edited by users directly.
CREATE TABLE library_items (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  project_id        CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  folder_id         CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  item_type         ENUM('REEL','REPORT','MATCH','FOLDER','EXPORT','TEMPLATE','CLIP','VIDEO') NOT NULL COMMENT 'Type pill',
  entity_id         CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'PK of the domain row for item_type',
  title             VARCHAR(255) NOT NULL COMMENT 'Row title',
  subtitle          VARCHAR(255) NULL COMMENT 'Row subtitle (series / match label)',
  description       TEXT NULL COMMENT 'Selected Item description',
  status            ENUM('DRAFT','IN_REVIEW','PUBLISHED','SHARED','EXPORTED','ARCHIVED','FAILED') NOT NULL DEFAULT 'DRAFT' COMMENT 'Status pill',
  match_id          CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  competition_id    CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  primary_club_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  duration_us       BIGINT UNSIGNED NULL COMMENT 'Thumbnail duration chip / Duration row',
  byte_size         BIGINT UNSIGNED NULL COMMENT 'File Size row',
  width_px          SMALLINT UNSIGNED NULL,
  height_px         SMALLINT UNSIGNED NULL COMMENT 'Resolution row derived (e.g. 1080p)',
  thumbnail_asset_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  primary_asset_id  CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'Download target',
  is_featured       BOOLEAN NOT NULL DEFAULT FALSE COMMENT '01 Home FEATURED REEL',
  is_template       BOOLEAN NOT NULL DEFAULT FALSE,
  shared_with_count INT UNSIGNED NOT NULL DEFAULT 0,
  created_by        CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Created By row',
  curated_at        DATETIME(6) NULL COMMENT 'Curated row',
  created_at        DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at        DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT 'Updated column (domain last change, set by projector)',
  deleted_at        DATETIME(6) NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_library_items_org_id (organization_id, id),
  UNIQUE KEY uq_library_items_entity (organization_id, item_type, entity_id),
  KEY ix_library_tab (organization_id, item_type, deleted_at, updated_at),
  KEY ix_library_status (organization_id, status, updated_at),
  KEY ix_library_comp (organization_id, competition_id, updated_at),
  KEY ix_library_club (organization_id, primary_club_id, updated_at),
  KEY ix_library_creator (organization_id, created_by, updated_at),
  KEY ix_library_folder (organization_id, folder_id),
  KEY ix_library_featured (organization_id, is_featured, updated_at),
  FULLTEXT KEY ft_library_search (title, subtitle, description),
  CONSTRAINT fk_li_org     FOREIGN KEY (organization_id) REFERENCES organizations(id),
  CONSTRAINT fk_li_project FOREIGN KEY (organization_id, project_id) REFERENCES projects(organization_id, id),
  CONSTRAINT fk_li_folder  FOREIGN KEY (organization_id, folder_id) REFERENCES folders(organization_id, id),
  CONSTRAINT fk_li_match   FOREIGN KEY (organization_id, match_id) REFERENCES matches(organization_id, id),
  CONSTRAINT fk_li_comp    FOREIGN KEY (competition_id) REFERENCES competitions(id),
  CONSTRAINT fk_li_club    FOREIGN KEY (primary_club_id) REFERENCES clubs(id),
  CONSTRAINT fk_li_thumb   FOREIGN KEY (organization_id, thumbnail_asset_id) REFERENCES assets(organization_id, id),
  CONSTRAINT fk_li_primary FOREIGN KEY (organization_id, primary_asset_id) REFERENCES assets(organization_id, id),
  CONSTRAINT fk_li_creator FOREIGN KEY (created_by) REFERENCES users(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE library_item_players (
  library_item_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  player_id         CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  display_order     SMALLINT UNSIGNED NOT NULL DEFAULT 0 COMMENT 'Players Featured avatars (first N + "+n")',
  PRIMARY KEY (library_item_id, player_id),
  KEY ix_lip_player (organization_id, player_id),
  CONSTRAINT fk_lip_item   FOREIGN KEY (organization_id, library_item_id) REFERENCES library_items(organization_id, id) ON DELETE CASCADE,
  CONSTRAINT fk_lip_player FOREIGN KEY (player_id) REFERENCES players(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE library_item_tags (
  library_item_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  tag_id            CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  PRIMARY KEY (library_item_id, tag_id),
  KEY ix_lit_tag (organization_id, tag_id),
  CONSTRAINT fk_lit_item FOREIGN KEY (organization_id, library_item_id) REFERENCES library_items(organization_id, id) ON DELETE CASCADE,
  CONSTRAINT fk_lit_tag  FOREIGN KEY (organization_id, tag_id) REFERENCES tags(organization_id, id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE library_item_collaborators (
  library_item_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  user_id           CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  access            ENUM('VIEW','COMMENT','EDIT','OWNER') NOT NULL DEFAULT 'VIEW',
  added_by          CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  added_at          DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (library_item_id, user_id),
  KEY ix_lic_user (organization_id, user_id),
  CONSTRAINT fk_lic_item   FOREIGN KEY (organization_id, library_item_id) REFERENCES library_items(organization_id, id) ON DELETE CASCADE,
  CONSTRAINT fk_lic_member FOREIGN KEY (organization_id, user_id) REFERENCES memberships(organization_id, user_id) ON DELETE CASCADE,
  CONSTRAINT fk_lic_adder  FOREIGN KEY (added_by) REFERENCES users(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='Collaborators column / Selected Item Collaborators / Manage Access';

CREATE TABLE saved_searches (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  user_id           CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  name              VARCHAR(80) NOT NULL COMMENT 'Saved Searches chip label',
  icon              ENUM('SEARCH','GRID') NOT NULL DEFAULT 'SEARCH',
  query             JSON NOT NULL COMMENT '{text,type,competitionId,clubId,createdBy,dateRange,tab}',
  display_order     SMALLINT UNSIGNED NOT NULL DEFAULT 0,
  created_at        DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (id),
  UNIQUE KEY uq_saved_searches_name (organization_id, user_id, name),
  CONSTRAINT fk_ss_member FOREIGN KEY (organization_id, user_id) REFERENCES memberships(organization_id, user_id) ON DELETE CASCADE,
  CONSTRAINT ck_ss_query CHECK (JSON_SCHEMA_VALID('{"type":"object","additionalProperties":false,"properties":{
      "text":{"type":"string","maxLength":200},"tab":{"type":"string"},"type":{"type":"string"},
      "competitionId":{"type":"string"},"clubId":{"type":"string"},"createdBy":{"type":"string"},
      "dateRange":{"type":"string","enum":["LAST_7_DAYS","LAST_30_DAYS","LAST_3_MONTHS","LAST_12_MONTHS","ALL","CUSTOM"]},
      "from":{"type":"string"},"to":{"type":"string"}}}', query))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE bookmarks (
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  user_id           CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  library_item_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  created_at        DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (organization_id, user_id, library_item_id),
  CONSTRAINT fk_bm_member FOREIGN KEY (organization_id, user_id) REFERENCES memberships(organization_id, user_id) ON DELETE CASCADE,
  CONSTRAINT fk_bm_item   FOREIGN KEY (organization_id, library_item_id) REFERENCES library_items(organization_id, id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='01 Home sample-reel bookmark icon';

CREATE TABLE item_engagement_daily (
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  library_item_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  day               DATE NOT NULL,
  views             INT UNSIGNED NOT NULL DEFAULT 0,
  likes             INT UNSIGNED NOT NULL DEFAULT 0,
  shares            INT UNSIGNED NOT NULL DEFAULT 0,
  downloads         INT UNSIGNED NOT NULL DEFAULT 0,
  PRIMARY KEY (organization_id, library_item_id, day),
  CONSTRAINT fk_ied_item FOREIGN KEY (organization_id, library_item_id) REFERENCES library_items(organization_id, id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='01 Home eye/heart counts = SUM over item; written by share/playback event consumers';

CREATE TABLE item_likes (
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  library_item_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  user_id           CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  created_at        DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (organization_id, library_item_id, user_id),
  CONSTRAINT fk_il_item   FOREIGN KEY (organization_id, library_item_id) REFERENCES library_items(organization_id, id) ON DELETE CASCADE,
  CONSTRAINT fk_il_member FOREIGN KEY (organization_id, user_id) REFERENCES memberships(organization_id, user_id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE comments (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  library_item_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  project_id        CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  parent_comment_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  author_user_id    CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  author_share_link_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'External reviewer via share link with Allow Comments',
  body              VARCHAR(4000) NOT NULL,
  at_pts_us         BIGINT UNSIGNED NULL,
  resolved_at       DATETIME(6) NULL,
  created_at        DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (id),
  UNIQUE KEY uq_comments_org_id (organization_id, id),
  KEY ix_comments_item (organization_id, library_item_id, created_at),
  CONSTRAINT fk_comments_item   FOREIGN KEY (organization_id, library_item_id) REFERENCES library_items(organization_id, id) ON DELETE CASCADE,
  CONSTRAINT fk_comments_proj   FOREIGN KEY (organization_id, project_id) REFERENCES projects(organization_id, id),
  CONSTRAINT fk_comments_parent FOREIGN KEY (organization_id, parent_comment_id) REFERENCES comments(organization_id, id),
  CONSTRAINT fk_comments_author FOREIGN KEY (author_user_id) REFERENCES users(id),
  CONSTRAINT ck_comments_author CHECK (author_user_id IS NOT NULL OR author_share_link_id IS NOT NULL)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

-- ===== 004_media_ingest_rights.sql =====
-- Migration 004 — Video sources, ingest options (02 toggles), uploads, URL imports, probing, classification, rights
USE `otsi_owner_vie`;

CREATE TABLE supported_media_formats (
  container_code    VARCHAR(10) CHARACTER SET ascii NOT NULL COMMENT 'MP4, MOV, AVI, MKV, MPEG, FLV, TS, WEBM',
  display_name      VARCHAR(20) NOT NULL,
  codec_summary     VARCHAR(40) NOT NULL COMMENT 'Format chip subtitle e.g. H.264/H.265',
  mime_types        JSON NOT NULL,
  file_extensions   JSON NOT NULL,
  accepted          BOOLEAN NOT NULL DEFAULT TRUE,
  display_order     TINYINT UNSIGNED NOT NULL,
  PRIMARY KEY (container_code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='02 Supported Formats panel; also the server-side ingest allow-list';

CREATE TABLE ingest_limits (
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  max_file_bytes    BIGINT UNSIGNED NOT NULL COMMENT 'Copy currently conflicts: 01 "2GB" vs 02 "50 GB" — owner must set one value',
  max_duration_us   BIGINT UNSIGNED NULL,
  max_concurrent_uploads SMALLINT UNSIGNED NOT NULL DEFAULT 3,
  updated_at        DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  PRIMARY KEY (organization_id),
  CONSTRAINT fk_ingest_limits_org FOREIGN KEY (organization_id) REFERENCES organizations(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE video_sources (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  project_id        CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  match_id          CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'Match Context: Match select (optional)',
  source_asset_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  proxy_asset_id    CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'Browser playback rendition (HLS/MP4)',
  poster_asset_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'Thumbnails in recent lists / previews',
  ingest_mode       ENUM('UPLOAD','DIRECT_URL','AUTHORIZED_PROVIDER','BATCH') NOT NULL COMMENT 'Upload method tabs',
  batch_id          CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  source_uri        VARCHAR(2048) NULL,
  title             VARCHAR(255) NULL,
  state             ENUM('PENDING','UPLOADING','VALIDATING','INGESTED','FAILED','QUARANTINED','DELETED') NOT NULL DEFAULT 'PENDING',
  failure_code      VARCHAR(64) CHARACTER SET ascii NULL,
  duration_us       BIGINT UNSIGNED NULL COMMENT 'Duration row / thumbnail chip',
  width_px          SMALLINT UNSIGNED NULL,
  height_px         SMALLINT UNSIGNED NULL,
  fps_num           INT UNSIGNED NULL,
  fps_den           INT UNSIGNED NULL,
  fps               DECIMAL(9,4) AS (IF(fps_den IS NULL OR fps_den = 0, NULL, fps_num / fps_den)) STORED COMMENT 'Frame Rate row',
  timebase_num      INT UNSIGNED NULL,
  timebase_den      INT UNSIGNED NULL,
  frame_count       BIGINT UNSIGNED NULL,
  video_codec       VARCHAR(32) CHARACTER SET ascii NULL,
  audio_codec       VARCHAR(32) CHARACTER SET ascii NULL,
  container_code    VARCHAR(10) CHARACTER SET ascii NULL,
  bitrate_bps       BIGINT UNSIGNED NULL,
  video_sha256      CHAR(64) CHARACTER SET ascii NULL,
  created_by        CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  created_at        DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  ingested_at       DATETIME(6) NULL,
  updated_at        DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  row_version       BIGINT UNSIGNED NOT NULL DEFAULT 1,
  PRIMARY KEY (id),
  UNIQUE KEY uq_video_sources_org_id (organization_id, id),
  KEY ix_vs_org_recent (organization_id, created_at),
  KEY ix_vs_match (organization_id, match_id),
  KEY ix_vs_state (organization_id, state, created_at),
  KEY ix_vs_sha (organization_id, video_sha256),
  CONSTRAINT fk_vs_project FOREIGN KEY (organization_id, project_id) REFERENCES projects(organization_id, id),
  CONSTRAINT fk_vs_match   FOREIGN KEY (organization_id, match_id) REFERENCES matches(organization_id, id),
  CONSTRAINT fk_vs_source  FOREIGN KEY (organization_id, source_asset_id) REFERENCES assets(organization_id, id),
  CONSTRAINT fk_vs_proxy   FOREIGN KEY (organization_id, proxy_asset_id) REFERENCES assets(organization_id, id),
  CONSTRAINT fk_vs_poster  FOREIGN KEY (organization_id, poster_asset_id) REFERENCES assets(organization_id, id),
  CONSTRAINT fk_vs_format  FOREIGN KEY (container_code) REFERENCES supported_media_formats(container_code),
  CONSTRAINT fk_vs_user    FOREIGN KEY (created_by) REFERENCES users(id),
  CONSTRAINT ck_vs_ingested CHECK (state <> 'INGESTED' OR (source_asset_id IS NOT NULL AND COALESCE(duration_us, 0) > 0 AND COALESCE(width_px, 0) > 0
                                    AND COALESCE(height_px, 0) > 0 AND COALESCE(fps_num, 0) > 0 AND COALESCE(fps_den, 0) > 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

-- 02 left column toggles: Visual Processing, AI Overlays (Auto-Detect), Ingest Options. One row per video (immutable after run start).
CREATE TABLE video_ingest_options (
  video_id          CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  stabilize_video   BOOLEAN NOT NULL DEFAULT TRUE,
  auto_crop_pitch   BOOLEAN NOT NULL DEFAULT TRUE,
  enhance_quality   BOOLEAN NOT NULL DEFAULT TRUE,
  remove_crowd_noise BOOLEAN NOT NULL DEFAULT FALSE,
  correct_aspect_ratio BOOLEAN NOT NULL DEFAULT TRUE,
  overlay_players_teams BOOLEAN NOT NULL DEFAULT TRUE,
  overlay_ball_tracking BOOLEAN NOT NULL DEFAULT TRUE,
  overlay_jersey_numbers BOOLEAN NOT NULL DEFAULT TRUE,
  overlay_pitch_lines BOOLEAN NOT NULL DEFAULT TRUE,
  overlay_event_markers BOOLEAN NOT NULL DEFAULT FALSE,
  auto_create_match BOOLEAN NOT NULL DEFAULT TRUE,
  extract_metadata  BOOLEAN NOT NULL DEFAULT TRUE,
  generate_highlights BOOLEAN NOT NULL DEFAULT FALSE,
  send_to_analysis  BOOLEAN NOT NULL DEFAULT TRUE,
  locked_at         DATETIME(6) NULL COMMENT 'Set when first pipeline run starts; changes require a new run',
  updated_by        CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  updated_at        DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  PRIMARY KEY (video_id),
  CONSTRAINT fk_vio_video FOREIGN KEY (organization_id, video_id) REFERENCES video_sources(organization_id, id) ON DELETE CASCADE,
  CONSTRAINT fk_vio_user  FOREIGN KEY (updated_by) REFERENCES users(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE ingest_batches (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  project_id        CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  label             VARCHAR(150) NULL,
  item_count        SMALLINT UNSIGNED NOT NULL DEFAULT 0,
  created_by        CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  created_at        DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (id),
  UNIQUE KEY uq_ingest_batches_org_id (organization_id, id),
  CONSTRAINT fk_ib_project FOREIGN KEY (organization_id, project_id) REFERENCES projects(organization_id, id),
  CONSTRAINT fk_ib_user    FOREIGN KEY (created_by) REFERENCES users(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='02 Batch Upload tab';

ALTER TABLE video_sources ADD CONSTRAINT fk_vs_batch FOREIGN KEY (organization_id, batch_id) REFERENCES ingest_batches(organization_id, id);

CREATE TABLE upload_sessions (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  video_id          CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  created_by        CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  idempotency_key   VARCHAR(128) CHARACTER SET ascii NOT NULL,
  multipart_upload_id VARCHAR(255) CHARACTER SET ascii NULL,
  original_filename VARCHAR(512) NOT NULL,
  declared_mime_type VARCHAR(127) CHARACTER SET ascii NULL,
  expected_bytes    BIGINT UNSIGNED NOT NULL,
  expected_sha256   CHAR(64) CHARACTER SET ascii NULL,
  part_size_bytes   INT UNSIGNED NOT NULL DEFAULT 67108864,
  transferred_bytes BIGINT UNSIGNED NOT NULL DEFAULT 0,
  progress_pct      DECIMAL(5,2) AS (LEAST(100, ROUND(transferred_bytes * 100 / expected_bytes, 2))) STORED COMMENT 'Uploading stage percent',
  status            ENUM('INITIALIZED','UPLOADING','VERIFYING','COMPLETED','ABORTED','EXPIRED','FAILED') NOT NULL DEFAULT 'INITIALIZED',
  failure_code      VARCHAR(64) CHARACTER SET ascii NULL,
  expires_at        DATETIME(6) NOT NULL,
  created_at        DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  completed_at      DATETIME(6) NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_upload_idem (organization_id, idempotency_key),
  KEY ix_upload_video (organization_id, video_id),
  KEY ix_upload_expiry (status, expires_at),
  CONSTRAINT fk_upload_video FOREIGN KEY (organization_id, video_id) REFERENCES video_sources(organization_id, id),
  CONSTRAINT fk_upload_user  FOREIGN KEY (created_by) REFERENCES users(id),
  CONSTRAINT ck_upload_bytes CHECK (expected_bytes > 0 AND transferred_bytes <= expected_bytes)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE upload_parts (
  session_id        CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  part_number       SMALLINT UNSIGNED NOT NULL,
  byte_size         BIGINT UNSIGNED NOT NULL,
  remote_etag       VARCHAR(255) CHARACTER SET ascii NOT NULL,
  part_sha256       CHAR(64) CHARACTER SET ascii NULL,
  received_at       DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (session_id, part_number),
  CONSTRAINT fk_upload_parts_session FOREIGN KEY (session_id) REFERENCES upload_sessions(id) ON DELETE CASCADE,
  CONSTRAINT ck_upload_parts CHECK (part_number BETWEEN 1 AND 10000 AND byte_size > 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE url_imports (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  video_id          CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  submitted_url     VARCHAR(2048) NOT NULL COMMENT '"Paste YouTube link or direct video URL..."',
  provider          ENUM('DIRECT_HTTP','YOUTUBE','HUDL','WYSCOUT','VEO','OTHER_AUTHORIZED') NOT NULL,
  provider_account_ref VARCHAR(255) NULL COMMENT 'Licensed integration credential reference (secret manager key, never the secret)',
  resolved_host     VARCHAR(255) NULL,
  ssrf_check_passed BOOLEAN NOT NULL DEFAULT FALSE,
  terms_check_state ENUM('PENDING','ALLOWED','DENIED') NOT NULL DEFAULT 'PENDING',
  status            ENUM('QUEUED','FETCHING','COMPLETED','REJECTED','FAILED') NOT NULL DEFAULT 'QUEUED',
  failure_code      VARCHAR(64) CHARACTER SET ascii NULL,
  created_by        CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  created_at        DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (id),
  KEY ix_url_imports_video (organization_id, video_id),
  CONSTRAINT fk_url_video FOREIGN KEY (organization_id, video_id) REFERENCES video_sources(organization_id, id),
  CONSTRAINT fk_url_user  FOREIGN KEY (created_by) REFERENCES users(id),
  CONSTRAINT ck_url_fetch_gate CHECK (status NOT IN ('FETCHING','COMPLETED') OR (ssrf_check_passed AND terms_check_state = 'ALLOWED'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE video_classifications (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  video_id          CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  content_class     ENUM('MATCH','TRAINING','HIGHLIGHTS','INTERVIEW','OTHER') NOT NULL COMMENT '"Detected Content"',
  confidence        DECIMAL(5,4) NULL,
  confidence_band   ENUM('HIGH','MEDIUM','LOW') NULL COMMENT '"(High Confidence)"',
  evidence_state    ENUM('DETECTED','INFERRED','CONFIRMED','NOT_MEASURED') NOT NULL DEFAULT 'INFERRED',
  model_version_id  CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  confirmed_by      CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  created_at        DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (id),
  KEY ix_vc_video (organization_id, video_id, created_at),
  CONSTRAINT fk_vc_video FOREIGN KEY (organization_id, video_id) REFERENCES video_sources(organization_id, id) ON DELETE CASCADE,
  CONSTRAINT fk_vc_user  FOREIGN KEY (confirmed_by) REFERENCES users(id),
  CONSTRAINT ck_vc_conf  CHECK (confidence IS NULL OR confidence BETWEEN 0 AND 1),
  CONSTRAINT ck_vc_confirmed CHECK (evidence_state <> 'CONFIRMED' OR confirmed_by IS NOT NULL)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

-- "Teams (Detected)" on 02 Selected Item Preview: model proposals that must be confirmed against the match.
CREATE TABLE video_detected_teams (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  video_id          CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  side              ENUM('HOME','AWAY','UNKNOWN') NOT NULL,
  cluster_label     VARCHAR(20) NOT NULL COMMENT 'Team cluster from kit segmentation, e.g. A / B',
  kit_color_hex     CHAR(7) CHARACTER SET ascii NULL,
  kit_color_name    VARCHAR(30) NULL,
  proposed_club_id  CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  confidence        DECIMAL(5,4) NULL,
  evidence_state    ENUM('DETECTED','INFERRED','CONFIRMED','NOT_MEASURED') NOT NULL DEFAULT 'INFERRED',
  confirmed_club_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  confirmed_by      CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_vdt (video_id, cluster_label),
  CONSTRAINT fk_vdt_video FOREIGN KEY (organization_id, video_id) REFERENCES video_sources(organization_id, id) ON DELETE CASCADE,
  CONSTRAINT fk_vdt_prop  FOREIGN KEY (proposed_club_id) REFERENCES clubs(id),
  CONSTRAINT fk_vdt_conf  FOREIGN KEY (confirmed_club_id) REFERENCES clubs(id),
  CONSTRAINT fk_vdt_user  FOREIGN KEY (confirmed_by) REFERENCES users(id),
  CONSTRAINT ck_vdt_confirm CHECK (evidence_state <> 'CONFIRMED' OR (confirmed_club_id IS NOT NULL AND confirmed_by IS NOT NULL))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE rights_grants (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  video_id          CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  asset_id          CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  rights_state      ENUM('UNKNOWN','ANALYSIS_ONLY','INTERNAL','EXPORT_ALLOWED','PUBLIC','EXPIRED','REVOKED') NOT NULL DEFAULT 'UNKNOWN',
  allowed_uses      JSON NOT NULL DEFAULT (JSON_ARRAY()) COMMENT '["ANALYZE","PRODUCE","EXPORT","SHARE","DELIVER","PUBLIC_POST"]',
  territory_codes   JSON NOT NULL DEFAULT (JSON_ARRAY()),
  licensor          VARCHAR(200) NULL,
  valid_from        DATETIME(6) NULL,
  valid_until       DATETIME(6) NULL,
  guardian_consent_state ENUM('NOT_APPLICABLE','PENDING','VERIFIED','REVOKED') NOT NULL DEFAULT 'NOT_APPLICABLE',
  evidence_asset_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  recorded_by       CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  created_at        DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (id),
  KEY ix_rights_video (organization_id, video_id, rights_state),
  KEY ix_rights_asset (organization_id, asset_id, rights_state),
  CONSTRAINT fk_rights_video FOREIGN KEY (organization_id, video_id) REFERENCES video_sources(organization_id, id),
  CONSTRAINT fk_rights_asset FOREIGN KEY (organization_id, asset_id) REFERENCES assets(organization_id, id),
  CONSTRAINT fk_rights_evid  FOREIGN KEY (organization_id, evidence_asset_id) REFERENCES assets(organization_id, id),
  CONSTRAINT fk_rights_user  FOREIGN KEY (recorded_by) REFERENCES users(id),
  CONSTRAINT ck_rights_target CHECK (video_id IS NOT NULL OR asset_id IS NOT NULL),
  CONSTRAINT ck_rights_range  CHECK (valid_until IS NULL OR valid_from IS NULL OR valid_until > valid_from),
  CONSTRAINT ck_rights_uses   CHECK (JSON_TYPE(allowed_uses) = 'ARRAY')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE video_shots (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  video_id          CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  start_pts_us      BIGINT UNSIGNED NOT NULL,
  end_pts_us        BIGINT UNSIGNED NOT NULL,
  camera_class      ENUM('WIDE_TACTICAL','BROADCAST_MAIN','CLOSE_UP','REPLAY','CROWD','GRAPHIC','OTHER') NULL,
  confidence        DECIMAL(5,4) NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_shots_start (video_id, start_pts_us),
  CONSTRAINT fk_shots_video FOREIGN KEY (organization_id, video_id) REFERENCES video_sources(organization_id, id) ON DELETE CASCADE,
  CONSTRAINT ck_shots_range CHECK (end_pts_us > start_pts_us)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE video_frame_index (
  video_id          CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  frame_index       INT UNSIGNED NOT NULL,
  pts_us            BIGINT UNSIGNED NOT NULL,
  shot_id           CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  is_keyframe       BOOLEAN NOT NULL DEFAULT FALSE,
  PRIMARY KEY (video_id, frame_index),
  UNIQUE KEY uq_frame_pts (video_id, pts_us)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='High volume (~170k rows per 95-min match at 30fps). Written in bulk by the worker; FKs omitted by design, integrity checked by orphan job.';

-- ===== 005_pipeline_cv_identity.sql =====
-- Migration 005 — AI pipeline (03), workers/resources, models, evidence, detection, tracking, identity resolution
USE `otsi_owner_vie`;

CREATE TABLE model_versions (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  task              ENUM('VIDEO_CLASSIFY','SHOT_DETECT','PLAYER_DETECT','BALL_DETECT','TRACK','REID','JERSEY_OCR','TEAM_CLUSTER',
                         'PITCH_KEYPOINTS','EVENT_DETECT','FORMATION','XG','XA','INSIGHT_LLM','CAPTION_ASR','HIGHLIGHT_RANK') NOT NULL,
  model_name        VARCHAR(100) NOT NULL,
  semantic_version  VARCHAR(40) NOT NULL,
  weights_sha256    CHAR(64) CHARACTER SET ascii NOT NULL,
  license_id        VARCHAR(120) NOT NULL COMMENT 'Commercial licence evidence required (ADR-009)',
  approval_state    ENUM('CANDIDATE','APPROVED','DEPRECATED','REVOKED') NOT NULL DEFAULT 'CANDIDATE',
  approved_by       CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  approved_at       DATETIME(6) NULL,
  config            JSON NOT NULL DEFAULT (JSON_OBJECT()),
  created_at        DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (id),
  UNIQUE KEY uq_model_versions (task, model_name, semantic_version),
  KEY ix_model_task_state (task, approval_state),
  CONSTRAINT fk_mv_approver FOREIGN KEY (approved_by) REFERENCES users(id),
  CONSTRAINT ck_mv_approved CHECK (approval_state <> 'APPROVED' OR (approved_by IS NOT NULL AND approved_at IS NOT NULL))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

ALTER TABLE video_classifications ADD CONSTRAINT fk_vc_model FOREIGN KEY (model_version_id) REFERENCES model_versions(id);

CREATE TABLE model_evaluation_sets (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  name              VARCHAR(150) NOT NULL,
  dataset_sha256    CHAR(64) CHARACTER SET ascii NOT NULL,
  license_note      TEXT NOT NULL,
  manifest_object_key VARCHAR(1024) NOT NULL,
  split_policy      VARCHAR(255) NOT NULL DEFAULT 'by fixture/stadium/camera',
  created_at        DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (id),
  UNIQUE KEY uq_mes_name (name)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE model_evaluation_runs (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  model_version_id  CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  evaluation_set_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  summary_metrics   JSON NOT NULL COMMENT 'mAP, HOTA, IDF1, event P/R, calibration ...',
  acceptance_state  ENUM('PENDING','PASSED','FAILED') NOT NULL DEFAULT 'PENDING',
  reviewed_by       CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  created_at        DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (id),
  KEY ix_mer_model (model_version_id, created_at),
  CONSTRAINT fk_mer_model FOREIGN KEY (model_version_id) REFERENCES model_versions(id),
  CONSTRAINT fk_mer_set   FOREIGN KEY (evaluation_set_id) REFERENCES model_evaluation_sets(id),
  CONSTRAINT fk_mer_user  FOREIGN KEY (reviewed_by) REFERENCES users(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

-- Display definitions of pipeline stages. 02 shows 5 user stages; 03 shows 5 AI stages; engine steps map onto them.
CREATE TABLE pipeline_stage_definitions (
  code              VARCHAR(24) CHARACTER SET ascii NOT NULL,
  engine_step       ENUM('VALIDATE','TRANSCODE','CLASSIFY','SHOTS','DETECT','TRACK','IDENTIFY','EVENTS','TACTICS','INDEX','QUALITY','FINISH') NOT NULL,
  ui_surface        ENUM('UPLOAD_PIPELINE','PROCESSING_PIPELINE','BOTH','INTERNAL') NOT NULL,
  ui_order          TINYINT UNSIGNED NOT NULL,
  label             VARCHAR(40) NOT NULL COMMENT 'e.g. "AI Detection", "Identity Resolution"',
  description       VARCHAR(160) NOT NULL COMMENT 'Stage card two-line description',
  timeline_color_hex CHAR(7) CHARACTER SET ascii NULL COMMENT '03 Processing Timeline legend colour',
  weight            DECIMAL(5,2) NOT NULL DEFAULT 1 COMMENT 'Contribution to overall progress',
  PRIMARY KEY (code),
  UNIQUE KEY uq_psd_step (engine_step)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE pipeline_runs (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  video_id          CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  attempt           SMALLINT UNSIGNED NOT NULL DEFAULT 1,
  retry_of_run_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  pipeline_version  VARCHAR(40) NOT NULL,
  workflow_id       VARCHAR(255) CHARACTER SET ascii NULL COMMENT 'Temporal workflow id',
  status            ENUM('QUEUED','RUNNING','SUCCEEDED','FAILED','CANCELLED','BLOCKED','REVIEW_REQUIRED') NOT NULL DEFAULT 'QUEUED',
  overall_progress  DECIMAL(5,2) NOT NULL DEFAULT 0 COMMENT '03 job card bar + percent (single source; never two numbers)',
  eta_seconds       INT UNSIGNED NULL,
  frames_total      BIGINT UNSIGNED NULL,
  frames_processed  BIGINT UNSIGNED NOT NULL DEFAULT 0,
  config            JSON NOT NULL DEFAULT (JSON_OBJECT()) COMMENT 'Snapshot of video_ingest_options + model pins',
  idempotency_key   VARCHAR(128) CHARACTER SET ascii NOT NULL,
  requested_by      CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  queued_at         DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  started_at        DATETIME(6) NULL,
  finished_at       DATETIME(6) NULL,
  failure_code      VARCHAR(64) CHARACTER SET ascii NULL,
  failure_detail    TEXT NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_pipeline_runs_org_id (organization_id, id),
  UNIQUE KEY uq_pipeline_runs_idem (organization_id, idempotency_key),
  UNIQUE KEY uq_pipeline_runs_attempt (video_id, attempt),
  KEY ix_runs_org_status (organization_id, status, queued_at),
  CONSTRAINT fk_runs_video FOREIGN KEY (organization_id, video_id) REFERENCES video_sources(organization_id, id),
  CONSTRAINT fk_runs_retry FOREIGN KEY (organization_id, retry_of_run_id) REFERENCES pipeline_runs(organization_id, id),
  CONSTRAINT fk_runs_user  FOREIGN KEY (requested_by) REFERENCES users(id),
  CONSTRAINT ck_runs_progress CHECK (overall_progress BETWEEN 0 AND 100),
  CONSTRAINT ck_runs_frames CHECK (frames_total IS NULL OR frames_processed <= frames_total),
  CONSTRAINT ck_runs_succeeded CHECK (status <> 'SUCCEEDED' OR (overall_progress = 100 AND finished_at IS NOT NULL)),
  CONSTRAINT ck_runs_failed CHECK (status <> 'FAILED' OR failure_code IS NOT NULL)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE pipeline_steps (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  run_id            CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  stage_code        VARCHAR(24) CHARACTER SET ascii NOT NULL,
  status            ENUM('QUEUED','RUNNING','SUCCEEDED','FAILED','CANCELLED','BLOCKED','REVIEW_REQUIRED') NOT NULL DEFAULT 'QUEUED' COMMENT 'Pills: Completed / Processing / In Queue / Waiting',
  attempt           SMALLINT UNSIGNED NOT NULL DEFAULT 0,
  progress          DECIMAL(5,2) NOT NULL DEFAULT 0,
  frame_from        BIGINT UNSIGNED NULL COMMENT 'Processing Timeline segment start',
  frame_to          BIGINT UNSIGNED NULL,
  model_version_id  CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  output_asset_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  error_code        VARCHAR(64) CHARACTER SET ascii NULL,
  started_at        DATETIME(6) NULL,
  completed_at      DATETIME(6) NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_steps_run_stage (run_id, stage_code),
  KEY ix_steps_org (organization_id, run_id),
  CONSTRAINT fk_steps_run   FOREIGN KEY (organization_id, run_id) REFERENCES pipeline_runs(organization_id, id) ON DELETE CASCADE,
  CONSTRAINT fk_steps_stage FOREIGN KEY (stage_code) REFERENCES pipeline_stage_definitions(code),
  CONSTRAINT fk_steps_model FOREIGN KEY (model_version_id) REFERENCES model_versions(id),
  CONSTRAINT fk_steps_asset FOREIGN KEY (output_asset_id) REFERENCES assets(id),
  CONSTRAINT ck_steps_progress CHECK (progress BETWEEN 0 AND 100),
  CONSTRAINT ck_steps_done CHECK (status <> 'SUCCEEDED' OR progress = 100)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

-- Frame-level progress segments for the 03 Processing Timeline (two lanes, coloured by stage).
CREATE TABLE pipeline_step_segments (
  id                BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  step_id           CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  lane              TINYINT UNSIGNED NOT NULL DEFAULT 1,
  from_pts_us       BIGINT UNSIGNED NOT NULL,
  to_pts_us         BIGINT UNSIGNED NOT NULL,
  state             ENUM('DONE','ACTIVE','PENDING','FAILED') NOT NULL,
  PRIMARY KEY (id),
  KEY ix_pss_step (step_id, lane, from_pts_us),
  CONSTRAINT fk_pss_step FOREIGN KEY (step_id) REFERENCES pipeline_steps(id) ON DELETE CASCADE,
  CONSTRAINT ck_pss_range CHECK (to_pts_us > from_pts_us)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

-- 03 Processing Log rows (time, check/pending icon, message). Also feeds SSE with Last-Event-ID = id.
CREATE TABLE job_log_entries (
  id                BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  run_id            CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  step_id           CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  level             ENUM('DEBUG','INFO','SUCCESS','WARN','ERROR') NOT NULL DEFAULT 'INFO',
  message_code      VARCHAR(64) CHARACTER SET ascii NOT NULL COMMENT 'Stable code for i18n, e.g. TRACKLETS_GENERATED',
  message           VARCHAR(500) NOT NULL COMMENT 'Rendered text, e.g. "Player tracklets generated (22)"',
  params            JSON NOT NULL DEFAULT (JSON_OBJECT()),
  is_pending        BOOLEAN NOT NULL DEFAULT FALSE COMMENT 'Pending rows render dimmed with empty circle',
  user_visible      BOOLEAN NOT NULL DEFAULT TRUE,
  occurred_at       DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (id),
  KEY ix_log_run (organization_id, run_id, id),
  CONSTRAINT fk_log_run FOREIGN KEY (organization_id, run_id) REFERENCES pipeline_runs(organization_id, id) ON DELETE CASCADE,
  CONSTRAINT fk_log_step FOREIGN KEY (step_id) REFERENCES pipeline_steps(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE worker_nodes (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  hostname          VARCHAR(255) NOT NULL,
  pool              ENUM('CV_GPU','RENDER_GPU','CPU','ASR') NOT NULL,
  gpu_model         VARCHAR(80) NULL COMMENT 'System Resources GPU caption, e.g. "NVIDIA A100"',
  gpu_count         TINYINT UNSIGNED NOT NULL DEFAULT 0,
  gpu_memory_bytes  BIGINT UNSIGNED NULL,
  cpu_cores         SMALLINT UNSIGNED NOT NULL COMMENT '"32 Cores"',
  memory_bytes      BIGINT UNSIGNED NOT NULL,
  storage_bytes_total BIGINT UNSIGNED NULL,
  status            ENUM('ONLINE','DRAINING','OFFLINE') NOT NULL DEFAULT 'ONLINE',
  last_heartbeat_at DATETIME(6) NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_worker_host (hostname)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='Platform-level (not tenant). Exposed to tenants only as aggregated, non-identifying figures';

CREATE TABLE worker_resource_samples (
  worker_id         CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  sampled_at        DATETIME(6) NOT NULL,
  gpu_util_pct      DECIMAL(5,2) NULL,
  cpu_util_pct      DECIMAL(5,2) NULL,
  memory_used_bytes BIGINT UNSIGNED NULL,
  storage_used_bytes BIGINT UNSIGNED NULL,
  PRIMARY KEY (worker_id, sampled_at),
  CONSTRAINT fk_wrs_worker FOREIGN KEY (worker_id) REFERENCES worker_nodes(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='03 System Resources rings + 14-bar sparklines; retain 24h (retention job)';

CREATE TABLE run_worker_assignments (
  run_id            CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  worker_id         CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  stage_code        VARCHAR(24) CHARACTER SET ascii NOT NULL,
  assigned_at       DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  released_at       DATETIME(6) NULL,
  PRIMARY KEY (run_id, worker_id, stage_code),
  CONSTRAINT fk_rwa_run    FOREIGN KEY (run_id) REFERENCES pipeline_runs(id) ON DELETE CASCADE,
  CONSTRAINT fk_rwa_worker FOREIGN KEY (worker_id) REFERENCES worker_nodes(id),
  CONSTRAINT fk_rwa_stage  FOREIGN KEY (stage_code) REFERENCES pipeline_stage_definitions(code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

-- Preview tiles: 02 Live Processing Preview (4 sub-stage thumbnails) and 03 four detection tiles.
CREATE TABLE pipeline_preview_frames (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  run_id            CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  preview_kind      ENUM('PLAYERS','BALL','TEAMS','EVENTS','METADATA','PROCESSING_VIEW') NOT NULL,
  pts_us            BIGINT UNSIGNED NOT NULL,
  frame_asset_id    CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  overlay           JSON NOT NULL DEFAULT (JSON_ARRAY()) COMMENT '[{trackId,bbox:[x,y,w,h],label,teamSide,confidence}]',
  headline_count    INT UNSIGNED NULL COMMENT '"22 players detected" / "1 ball detected"',
  headline_confidence DECIMAL(5,4) NULL COMMENT '"Ball 0.98"',
  created_at        DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (id),
  KEY ix_ppf_run_kind (organization_id, run_id, preview_kind, created_at),
  CONSTRAINT fk_ppf_run   FOREIGN KEY (organization_id, run_id) REFERENCES pipeline_runs(organization_id, id) ON DELETE CASCADE,
  CONSTRAINT fk_ppf_asset FOREIGN KEY (organization_id, frame_asset_id) REFERENCES assets(organization_id, id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE evidence_records (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  video_id          CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  pipeline_run_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  model_version_id  CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  state             ENUM('DETECTED','INFERRED','CONFIRMED','NOT_MEASURED') NOT NULL,
  source_type       ENUM('MODEL','HUMAN_REVIEW','OFFICIAL_FEED','ROSTER','CALIBRATION','DERIVED') NOT NULL,
  source_ref        VARCHAR(255) NOT NULL,
  frame_from        BIGINT UNSIGNED NULL,
  frame_to          BIGINT UNSIGNED NULL,
  confidence        DECIMAL(5,4) NULL,
  reviewer_id       CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  reviewed_at       DATETIME(6) NULL,
  notes             TEXT NULL,
  created_at        DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (id),
  UNIQUE KEY uq_evidence_org_id (organization_id, id),
  KEY ix_evidence_video (organization_id, video_id),
  CONSTRAINT fk_ev_video FOREIGN KEY (organization_id, video_id) REFERENCES video_sources(organization_id, id),
  CONSTRAINT fk_ev_run   FOREIGN KEY (organization_id, pipeline_run_id) REFERENCES pipeline_runs(organization_id, id),
  CONSTRAINT fk_ev_model FOREIGN KEY (model_version_id) REFERENCES model_versions(id),
  CONSTRAINT fk_ev_user  FOREIGN KEY (reviewer_id) REFERENCES users(id),
  CONSTRAINT ck_ev_confirmed CHECK (state <> 'CONFIRMED' OR (reviewer_id IS NOT NULL OR source_type IN ('OFFICIAL_FEED','ROSTER'))),
  CONSTRAINT ck_ev_conf CHECK (confidence IS NULL OR confidence BETWEEN 0 AND 1)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE detection_batches (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  run_id            CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  model_version_id  CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  start_frame       BIGINT UNSIGNED NOT NULL,
  end_frame         BIGINT UNSIGNED NOT NULL,
  payload_asset_id  CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Parquet in S3',
  checksum          CHAR(64) CHARACTER SET ascii NOT NULL,
  detection_count   BIGINT UNSIGNED NOT NULL,
  PRIMARY KEY (id),
  KEY ix_db_run (organization_id, run_id, start_frame),
  CONSTRAINT fk_db_run   FOREIGN KEY (organization_id, run_id) REFERENCES pipeline_runs(organization_id, id) ON DELETE CASCADE,
  CONSTRAINT fk_db_model FOREIGN KEY (model_version_id) REFERENCES model_versions(id),
  CONSTRAINT fk_db_asset FOREIGN KEY (organization_id, payload_asset_id) REFERENCES assets(organization_id, id),
  CONSTRAINT ck_db_range CHECK (end_frame >= start_frame)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE tracks (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  run_id            CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  video_id          CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  internal_track_number INT UNSIGNED NOT NULL COMMENT 'Anonymous visual id; NEVER shown as a player id',
  class_name        ENUM('PLAYER','GOALKEEPER','REFEREE','BALL','OTHER') NOT NULL,
  team_side         ENUM('HOME','AWAY','NEUTRAL','UNKNOWN') NOT NULL DEFAULT 'UNKNOWN' COMMENT 'Box colour cyan/amber',
  team_side_confidence DECIMAL(5,4) NULL,
  ocr_jersey_number TINYINT UNSIGNED NULL COMMENT 'Number tag on boxes (OCR evidence only)',
  ocr_jersey_confidence DECIMAL(5,4) NULL,
  first_pts_us      BIGINT UNSIGNED NOT NULL,
  last_pts_us       BIGINT UNSIGNED NOT NULL,
  observed_frames   INT UNSIGNED NOT NULL DEFAULT 0,
  status            ENUM('ACTIVE','OCCLUDED','LEFT_FRAME','ENDED','REVIEW_REQUIRED') NOT NULL DEFAULT 'ACTIVE',
  identity_state    ENUM('UNRESOLVED','CANDIDATE','CONFIRMED','REJECTED','CONFLICT') NOT NULL DEFAULT 'UNRESOLVED',
  current_player_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'Denormalised from latest CONFIRMED decision (set by trigger/service only)',
  current_decision_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  quality_score     DECIMAL(5,4) NULL,
  created_at        DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (id),
  UNIQUE KEY uq_tracks_org_id (organization_id, id),
  UNIQUE KEY uq_tracks_number (run_id, internal_track_number),
  KEY ix_tracks_video_class (organization_id, video_id, class_name, team_side),
  KEY ix_tracks_player (organization_id, current_player_id),
  CONSTRAINT fk_tracks_run    FOREIGN KEY (organization_id, run_id) REFERENCES pipeline_runs(organization_id, id),
  CONSTRAINT fk_tracks_video  FOREIGN KEY (organization_id, video_id) REFERENCES video_sources(organization_id, id),
  CONSTRAINT fk_tracks_player FOREIGN KEY (current_player_id) REFERENCES players(id),
  CONSTRAINT ck_tracks_range  CHECK (last_pts_us >= first_pts_us),
  CONSTRAINT ck_tracks_identity CHECK ((identity_state = 'CONFIRMED') = (current_player_id IS NOT NULL)),
  CONSTRAINT ck_tracks_ocr CHECK (ocr_jersey_number IS NULL OR ocr_jersey_number <= 99)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

-- Per-frame boxes: the highest-volume table. Partitioned by HASH of video for pruning; no FKs (MySQL forbids FKs on
-- partitioned InnoDB tables). Long-term storage is Parquet in S3; MySQL keeps a queryable window for overlays.
CREATE TABLE track_observations (
  video_id          CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  frame_index       INT UNSIGNED NOT NULL,
  track_id          CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  pts_us            BIGINT UNSIGNED NOT NULL,
  bbox_x            FLOAT NOT NULL,
  bbox_y            FLOAT NOT NULL,
  bbox_w            FLOAT NOT NULL,
  bbox_h            FLOAT NOT NULL,
  pitch_x_m         FLOAT NULL COMMENT 'Only when a calibration passed the quality gate',
  pitch_y_m         FLOAT NULL,
  detector_confidence FLOAT NULL,
  association_confidence FLOAT NULL,
  observation_state ENUM('DETECTED','PREDICTED','INTERPOLATED','REVIEWED') NOT NULL,
  PRIMARY KEY (video_id, frame_index, track_id),
  KEY ix_obs_track_pts (video_id, track_id, pts_us),
  KEY ix_obs_pts (video_id, pts_us),
  CONSTRAINT ck_obs_bbox CHECK (bbox_x BETWEEN 0 AND 1 AND bbox_y BETWEEN 0 AND 1 AND bbox_w > 0 AND bbox_h > 0
                                AND bbox_x + bbox_w <= 1.00001 AND bbox_y + bbox_h <= 1.00001)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC PARTITION BY KEY (video_id) PARTITIONS 32;

CREATE TABLE track_segments (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  track_id          CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  shot_id           CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  start_pts_us      BIGINT UNSIGNED NOT NULL,
  end_pts_us        BIGINT UNSIGNED NOT NULL,
  observation_asset_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  interpolation_policy ENUM('NONE','SHORT_GAP_LINEAR','KALMAN','REVIEWED') NOT NULL DEFAULT 'NONE',
  gap_count         INT UNSIGNED NOT NULL DEFAULT 0,
  quality_score     DECIMAL(5,4) NULL,
  PRIMARY KEY (id),
  KEY ix_ts_track (track_id, start_pts_us),
  CONSTRAINT fk_ts_track FOREIGN KEY (track_id) REFERENCES tracks(id) ON DELETE CASCADE,
  CONSTRAINT fk_ts_shot  FOREIGN KEY (shot_id) REFERENCES video_shots(id),
  CONSTRAINT fk_ts_asset FOREIGN KEY (observation_asset_id) REFERENCES assets(id),
  CONSTRAINT ck_ts_range CHECK (end_pts_us > start_pts_us)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE track_gaps (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  track_id          CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  start_pts_us      BIGINT UNSIGNED NOT NULL,
  end_pts_us        BIGINT UNSIGNED NOT NULL,
  gap_reason        ENUM('OCCLUDED','OUT_OF_FRAME','CAMERA_CUT','DETECTION_FAILURE','UNKNOWN') NOT NULL,
  PRIMARY KEY (id),
  KEY ix_tg_track (track_id, start_pts_us),
  CONSTRAINT fk_tg_track FOREIGN KEY (track_id) REFERENCES tracks(id) ON DELETE CASCADE,
  CONSTRAINT ck_tg_range CHECK (end_pts_us > start_pts_us)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

-- 04 "Tracks & Presence" lanes.
CREATE TABLE presence_intervals (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  video_id          CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  track_id          CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  start_pts_us      BIGINT UNSIGNED NOT NULL,
  end_pts_us        BIGINT UNSIGNED NOT NULL,
  observation_count INT UNSIGNED NOT NULL,
  PRIMARY KEY (id),
  KEY ix_pi_video (organization_id, video_id, start_pts_us),
  KEY ix_pi_track (track_id, start_pts_us),
  CONSTRAINT fk_pi_track FOREIGN KEY (organization_id, track_id) REFERENCES tracks(organization_id, id) ON DELETE CASCADE,
  CONSTRAINT fk_pi_video FOREIGN KEY (organization_id, video_id) REFERENCES video_sources(organization_id, id),
  CONSTRAINT ck_pi_range CHECK (end_pts_us > start_pts_us AND observation_count >= 1)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE track_identity_candidates (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  track_id          CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  player_id         CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  match_id          CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  score             DECIMAL(5,4) NOT NULL COMMENT '04 "Conf." column (identity task only)',
  rank_no           TINYINT UNSIGNED NOT NULL,
  evidence          JSON NOT NULL DEFAULT (JSON_OBJECT()) COMMENT '{ocrFrames:[], appearanceScore, kitScore, rosterMatch}',
  model_version_id  CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  created_at        DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (id),
  UNIQUE KEY uq_tic (track_id, player_id, model_version_id),
  KEY ix_tic_rank (organization_id, track_id, rank_no),
  CONSTRAINT fk_tic_track  FOREIGN KEY (organization_id, track_id) REFERENCES tracks(organization_id, id) ON DELETE CASCADE,
  CONSTRAINT fk_tic_player FOREIGN KEY (player_id) REFERENCES players(id),
  CONSTRAINT fk_tic_match  FOREIGN KEY (organization_id, match_id) REFERENCES matches(organization_id, id),
  CONSTRAINT fk_tic_model  FOREIGN KEY (model_version_id) REFERENCES model_versions(id),
  CONSTRAINT ck_tic_score  CHECK (score BETWEEN 0 AND 1)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

-- Append-only (UPDATE/DELETE blocked by trigger in 011). Latest row per track is the effective decision.
CREATE TABLE track_identity_decisions (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  track_id          CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  player_id         CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  state             ENUM('UNRESOLVED','CANDIDATE','CONFIRMED','REJECTED','CONFLICT') NOT NULL,
  basis             ENUM('HUMAN','AUTO_POLICY','REGISTRY') NOT NULL,
  policy_version    VARCHAR(40) NULL COMMENT 'Required for AUTO_POLICY confirmations',
  decided_by        CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  evidence_id       CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  supersedes_id     CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  valid_from_pts_us BIGINT UNSIGNED NULL COMMENT 'Partial-track decisions (ID switch handling)',
  valid_to_pts_us   BIGINT UNSIGNED NULL,
  reason            VARCHAR(500) NULL,
  decided_at        DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (id),
  UNIQUE KEY uq_tid_org_id (organization_id, id),
  UNIQUE KEY uq_tid_supersedes (supersedes_id),
  KEY ix_tid_track (organization_id, track_id, decided_at),
  CONSTRAINT fk_tid_track  FOREIGN KEY (organization_id, track_id) REFERENCES tracks(organization_id, id),
  CONSTRAINT fk_tid_player FOREIGN KEY (player_id) REFERENCES players(id),
  CONSTRAINT fk_tid_user   FOREIGN KEY (decided_by) REFERENCES users(id),
  CONSTRAINT fk_tid_evid   FOREIGN KEY (organization_id, evidence_id) REFERENCES evidence_records(organization_id, id),
  CONSTRAINT fk_tid_super  FOREIGN KEY (organization_id, supersedes_id) REFERENCES track_identity_decisions(organization_id, id),
  CONSTRAINT ck_tid_player CHECK (state NOT IN ('CONFIRMED','CANDIDATE') OR player_id IS NOT NULL),
  CONSTRAINT ck_tid_human  CHECK (basis <> 'HUMAN' OR decided_by IS NOT NULL),
  CONSTRAINT ck_tid_policy CHECK (basis <> 'AUTO_POLICY' OR policy_version IS NOT NULL),
  CONSTRAINT ck_tid_range  CHECK (valid_to_pts_us IS NULL OR valid_from_pts_us IS NULL OR valid_to_pts_us > valid_from_pts_us)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

ALTER TABLE tracks ADD CONSTRAINT fk_tracks_decision FOREIGN KEY (organization_id, current_decision_id) REFERENCES track_identity_decisions(organization_id, id);

CREATE TABLE identity_review_tasks (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  video_id          CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  track_id          CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  flag              ENUM('ID_SWITCH','MULTIPLE_CANDIDATES','OVERLAPPING_IDENTITY','BLURRY_JERSEY','KIT_AMBIGUITY','CALIBRATION_DISCONTINUITY',
                         'SHOT_CUT','LOW_COVERAGE','UNCERTAIN_BALL_EVENT','TARGET_DISAPPEARANCE','FALSE_POSITIVE') NOT NULL,
  priority          TINYINT UNSIGNED NOT NULL DEFAULT 50,
  status            ENUM('OPEN','IN_PROGRESS','RESOLVED','DISMISSED') NOT NULL DEFAULT 'OPEN',
  assigned_to       CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  resolution_decision_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  created_at        DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  resolved_at       DATETIME(6) NULL,
  PRIMARY KEY (id),
  KEY ix_irt_queue (organization_id, status, priority, created_at),
  CONSTRAINT fk_irt_track FOREIGN KEY (organization_id, track_id) REFERENCES tracks(organization_id, id),
  CONSTRAINT fk_irt_video FOREIGN KEY (organization_id, video_id) REFERENCES video_sources(organization_id, id),
  CONSTRAINT fk_irt_user  FOREIGN KEY (assigned_to) REFERENCES users(id),
  CONSTRAINT fk_irt_dec   FOREIGN KEY (organization_id, resolution_decision_id) REFERENCES track_identity_decisions(organization_id, id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE pitch_calibrations (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  video_id          CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  shot_id           CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  start_pts_us      BIGINT UNSIGNED NOT NULL,
  end_pts_us        BIGINT UNSIGNED NOT NULL,
  homography        JSON NOT NULL COMMENT '3x3 row-major',
  pitch_length_m    DECIMAL(5,1) NULL,
  pitch_width_m     DECIMAL(5,1) NULL,
  reprojection_error_px DECIMAL(8,3) NULL,
  quality_score     DECIMAL(5,4) NULL,
  passes_gate       BOOLEAN NOT NULL DEFAULT FALSE COMMENT 'Metric in metres allowed only when TRUE',
  evidence_state    ENUM('DETECTED','INFERRED','CONFIRMED','NOT_MEASURED') NOT NULL DEFAULT 'INFERRED',
  model_version_id  CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  PRIMARY KEY (id),
  KEY ix_pc_video (organization_id, video_id, start_pts_us),
  CONSTRAINT fk_pc_video FOREIGN KEY (organization_id, video_id) REFERENCES video_sources(organization_id, id) ON DELETE CASCADE,
  CONSTRAINT fk_pc_shot  FOREIGN KEY (shot_id) REFERENCES video_shots(id),
  CONSTRAINT fk_pc_model FOREIGN KEY (model_version_id) REFERENCES model_versions(id),
  CONSTRAINT ck_pc_range CHECK (end_pts_us > start_pts_us),
  CONSTRAINT ck_pc_h CHECK (JSON_LENGTH(homography) = 9)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

-- ===== 006_events_metrics_tactics.sql =====
-- Migration 006 — Event taxonomy & candidates (04, 08), metric registry & values (KPIs everywhere),
--                 cohorts/benchmarks (08 Comparison), tactical outputs (05)
USE `otsi_owner_vie`;

CREATE TABLE event_types (
  code              VARCHAR(32) CHARACTER SET ascii NOT NULL COMMENT 'PASS_ATTEMPT, KEY_PASS, SHOT_ATTEMPT, GOAL, TACKLE ...',
  label             VARCHAR(40) NOT NULL COMMENT 'Event chip / timeline type label',
  chip_group        VARCHAR(24) CHARACTER SET ascii NULL COMMENT '04 chips: GOALS, PASSES, KEY_PASSES, SHOTS, TACKLES, INTERCEPTIONS, FOULS, CARDS',
  lane_group        VARCHAR(24) CHARACTER SET ascii NULL COMMENT '04 Event Types lanes: GOALS, SHOTS, KEY_PASSES, PASSES, DUELS, DEFENSIVE',
  marker_group      VARCHAR(24) CHARACTER SET ascii NULL COMMENT '03 Event Markers legend: PASS, SHOT, TACKLE, FOUL, OFFSIDE',
  color_hex         CHAR(7) CHARACTER SET ascii NOT NULL,
  icon_key          VARCHAR(24) CHARACTER SET ascii NULL COMMENT '08 timeline icons person/key/tri/burst/star',
  is_ball_event     BOOLEAN NOT NULL DEFAULT TRUE,
  requires_review_for_confirmed BOOLEAN NOT NULL DEFAULT TRUE,
  ontology_version  VARCHAR(10) NOT NULL DEFAULT 'v1',
  sort_order        SMALLINT UNSIGNED NOT NULL,
  PRIMARY KEY (code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE event_candidates (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  run_id            CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  video_id          CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  match_id          CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  event_type        VARCHAR(32) CHARACTER SET ascii NOT NULL,
  start_pts_us      BIGINT UNSIGNED NOT NULL,
  end_pts_us        BIGINT UNSIGNED NOT NULL,
  period            ENUM('FIRST_HALF','SECOND_HALF','ET_FIRST','ET_SECOND','PENALTIES') NULL,
  match_clock_ms    INT UNSIGNED NULL COMMENT 'Displayed "62:17" (formatted client-side)',
  primary_track_id  CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  secondary_track_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  primary_player_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'Only when the track identity is CONFIRMED at event time',
  secondary_player_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  team_side         ENUM('HOME','AWAY','UNKNOWN') NOT NULL DEFAULT 'UNKNOWN',
  outcome           ENUM('SUCCESS','FAIL','UNKNOWN') NOT NULL DEFAULT 'UNKNOWN' COMMENT 'Pass network successful/unsuccessful',
  start_x_m         DECIMAL(6,2) NULL, start_y_m DECIMAL(6,2) NULL, end_x_m DECIMAL(6,2) NULL, end_y_m DECIMAL(6,2) NULL,
  calibration_id    CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'Required for pitch coordinates',
  description       VARCHAR(255) NULL COMMENT '08 Event Timeline description (generated from template + confirmed names)',
  confidence        DECIMAL(5,4) NULL,
  evidence_state    ENUM('DETECTED','INFERRED','CONFIRMED','NOT_MEASURED') NOT NULL DEFAULT 'DETECTED',
  effective_state   ENUM('PENDING','CONFIRMED','REJECTED','EDITED','NEEDS_REVIEW') NOT NULL DEFAULT 'PENDING' COMMENT 'Projection of latest decision',
  model_version_id  CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  evidence_id       CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  clip_asset_id     CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT '08 event thumbnail/play button',
  features          JSON NOT NULL DEFAULT (JSON_OBJECT()),
  created_at        DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (id),
  UNIQUE KEY uq_events_org_id (organization_id, id),
  KEY ix_events_video_time (organization_id, video_id, start_pts_us),
  KEY ix_events_video_type (organization_id, video_id, event_type, effective_state),
  KEY ix_events_player (organization_id, primary_player_id, event_type, start_pts_us),
  KEY ix_events_match (organization_id, match_id, event_type),
  CONSTRAINT fk_events_run    FOREIGN KEY (organization_id, run_id) REFERENCES pipeline_runs(organization_id, id),
  CONSTRAINT fk_events_video  FOREIGN KEY (organization_id, video_id) REFERENCES video_sources(organization_id, id),
  CONSTRAINT fk_events_match  FOREIGN KEY (organization_id, match_id) REFERENCES matches(organization_id, id),
  CONSTRAINT fk_events_type   FOREIGN KEY (event_type) REFERENCES event_types(code),
  CONSTRAINT fk_events_t1     FOREIGN KEY (organization_id, primary_track_id) REFERENCES tracks(organization_id, id),
  CONSTRAINT fk_events_t2     FOREIGN KEY (organization_id, secondary_track_id) REFERENCES tracks(organization_id, id),
  CONSTRAINT fk_events_p1     FOREIGN KEY (primary_player_id) REFERENCES players(id),
  CONSTRAINT fk_events_p2     FOREIGN KEY (secondary_player_id) REFERENCES players(id),
  CONSTRAINT fk_events_cal    FOREIGN KEY (calibration_id) REFERENCES pitch_calibrations(id),
  CONSTRAINT fk_events_model  FOREIGN KEY (model_version_id) REFERENCES model_versions(id),
  CONSTRAINT fk_events_evid   FOREIGN KEY (organization_id, evidence_id) REFERENCES evidence_records(organization_id, id),
  CONSTRAINT fk_events_clip   FOREIGN KEY (organization_id, clip_asset_id) REFERENCES assets(organization_id, id),
  CONSTRAINT ck_events_range  CHECK (end_pts_us >= start_pts_us),
  CONSTRAINT ck_events_coords CHECK (start_x_m IS NULL OR calibration_id IS NOT NULL),
  CONSTRAINT ck_events_conf   CHECK (confidence IS NULL OR confidence BETWEEN 0 AND 1)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE event_decisions (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  event_id          CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  decision          ENUM('CONFIRM','REJECT','EDIT','NEEDS_REVIEW') NOT NULL,
  reviewer_id       CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  revised_start_pts_us BIGINT UNSIGNED NULL,
  revised_end_pts_us BIGINT UNSIGNED NULL,
  revised_type      VARCHAR(32) CHARACTER SET ascii NULL,
  reason            VARCHAR(500) NULL,
  decided_at        DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (id),
  KEY ix_ed_event (organization_id, event_id, decided_at),
  CONSTRAINT fk_ed_event FOREIGN KEY (organization_id, event_id) REFERENCES event_candidates(organization_id, id),
  CONSTRAINT fk_ed_user  FOREIGN KEY (reviewer_id) REFERENCES users(id),
  CONSTRAINT fk_ed_type  FOREIGN KEY (revised_type) REFERENCES event_types(code),
  CONSTRAINT ck_ed_edit  CHECK (decision <> 'EDIT' OR revised_type IS NOT NULL OR revised_start_pts_us IS NOT NULL)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE metric_definitions (
  metric_key        VARCHAR(48) CHARACTER SET ascii NOT NULL COMMENT 'distance_m, top_speed_kmh, sprints, passes, pass_accuracy_pct ...',
  label             VARCHAR(60) NOT NULL COMMENT 'KPI tile / table label',
  unit              VARCHAR(16) NOT NULL COMMENT 'km, km/h, %, count, m, xG ...',
  display_decimals  TINYINT UNSIGNED NOT NULL DEFAULT 0,
  aggregation       ENUM('SUM','AVG','MAX','MIN','RATIO','LAST','MODEL') NOT NULL,
  subject_kind      ENUM('PLAYER','TEAM','MATCH','BALL','WORKSPACE') NOT NULL,
  measurement_class ENUM('PIXEL','PITCH_CALIBRATED','OBSERVED_EVENT','MODEL_ESTIMATE','HUMAN_REVIEW','OPERATIONAL') NOT NULL,
  requires_calibration BOOLEAN NOT NULL DEFAULT FALSE,
  minimum_quality   DECIMAL(5,4) NOT NULL DEFAULT 0,
  higher_is_better  BOOLEAN NULL,
  per90_supported   BOOLEAN NOT NULL DEFAULT FALSE,
  formula_version   VARCHAR(20) NOT NULL,
  description       VARCHAR(500) NOT NULL COMMENT 'Tooltip / report footnote',
  PRIMARY KEY (metric_key)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE metric_values (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  video_id          CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  match_id          CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  run_id            CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  subject_kind      ENUM('PLAYER','TEAM','MATCH','BALL','WORKSPACE') NOT NULL,
  player_id         CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  track_id          CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  team_side         ENUM('HOME','AWAY') NULL,
  metric_key        VARCHAR(48) CHARACTER SET ascii NOT NULL,
  window_kind       ENUM('FULL','PERIOD','RANGE','PHASE','ROLLING') NOT NULL DEFAULT 'FULL',
  period            ENUM('FIRST_HALF','SECOND_HALF','ET_FIRST','ET_SECOND') NULL,
  phase             ENUM('ALL','IN_POSSESSION','OUT_OF_POSSESSION','TRANSITION','SET_PIECE') NOT NULL DEFAULT 'ALL',
  start_pts_us      BIGINT UNSIGNED NULL,
  end_pts_us        BIGINT UNSIGNED NULL,
  value_numeric     DOUBLE NULL,
  value_per90       DOUBLE NULL,
  uncertainty       DOUBLE NULL COMMENT '± in metric unit',
  coverage_ratio    DECIMAL(5,4) NULL COMMENT 'Observed share of window (e.g. "92% of match")',
  baseline_value    DOUBLE NULL COMMENT 'Delta source for "↑ +8%"; NULL => no delta shown',
  baseline_ref      VARCHAR(80) NULL COMMENT 'e.g. season_avg:2024/2025, cohort:<id>',
  evidence_state    ENUM('DETECTED','INFERRED','CONFIRMED','NOT_MEASURED') NOT NULL,
  evidence_id       CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  quality_score     DECIMAL(5,4) NULL,
  model_version_id  CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  computed_at       DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  is_current        BOOLEAN NOT NULL DEFAULT TRUE COMMENT 'Previous versions kept, flagged FALSE on recompute',
  scope_key         VARCHAR(220) CHARACTER SET ascii AS (CONCAT_WS('|', video_id, match_id, subject_kind, player_id, track_id, team_side, metric_key,
                       window_kind, period, phase, start_pts_us, end_pts_us)) STORED,
  PRIMARY KEY (id),
  KEY ix_mv_player (organization_id, player_id, metric_key, is_current, computed_at),
  KEY ix_mv_video (organization_id, video_id, subject_kind, metric_key, is_current),
  KEY ix_mv_scope (organization_id, scope_key, is_current),
  CONSTRAINT fk_mv_video  FOREIGN KEY (organization_id, video_id) REFERENCES video_sources(organization_id, id),
  CONSTRAINT fk_mv_match  FOREIGN KEY (organization_id, match_id) REFERENCES matches(organization_id, id),
  CONSTRAINT fk_mv_run    FOREIGN KEY (organization_id, run_id) REFERENCES pipeline_runs(organization_id, id),
  CONSTRAINT fk_mv_player FOREIGN KEY (player_id) REFERENCES players(id),
  CONSTRAINT fk_mv_track  FOREIGN KEY (organization_id, track_id) REFERENCES tracks(organization_id, id),
  CONSTRAINT fk_mv_def    FOREIGN KEY (metric_key) REFERENCES metric_definitions(metric_key),
  CONSTRAINT fk_mv_evid   FOREIGN KEY (organization_id, evidence_id) REFERENCES evidence_records(organization_id, id),
  CONSTRAINT fk_mv_model  FOREIGN KEY (model_version_id) REFERENCES model_versions(id),
  CONSTRAINT ck_mv_not_measured CHECK (evidence_state <> 'NOT_MEASURED' OR (value_numeric IS NULL AND value_per90 IS NULL)),
  CONSTRAINT ck_mv_measured CHECK (evidence_state = 'NOT_MEASURED' OR value_numeric IS NOT NULL),
  CONSTRAINT ck_mv_subject CHECK (subject_kind <> 'PLAYER' OR player_id IS NOT NULL OR track_id IS NOT NULL),
  CONSTRAINT ck_mv_range CHECK (end_pts_us IS NULL OR start_pts_us IS NULL OR end_pts_us > start_pts_us),
  CONSTRAINT ck_mv_cov CHECK (coverage_ratio IS NULL OR coverage_ratio BETWEEN 0 AND 1)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE metric_cohorts (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  owner_organization_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  name              VARCHAR(120) NOT NULL COMMENT '08 select "vs. Midfielders (UCL 23/24)" / 05 "Attacking Midfielder"',
  version           VARCHAR(20) NOT NULL,
  definition        JSON NOT NULL COMMENT '{positions:[],competitionIds:[],seasonIds:[],minMinutes:..}',
  sample_count      INT UNSIGNED NULL,
  minimum_sample    INT UNSIGNED NOT NULL DEFAULT 10,
  created_at        DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (id),
  CONSTRAINT fk_mc_owner FOREIGN KEY (owner_organization_id) REFERENCES organizations(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE cohort_metric_baselines (
  cohort_id         CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  metric_key        VARCHAR(48) CHARACTER SET ascii NOT NULL,
  mean_per90        DOUBLE NULL COMMENT '"Midfielders Avg." bar',
  p50_per90         DOUBLE NULL,
  p90_per90         DOUBLE NULL,
  sample_count      INT UNSIGNED NOT NULL,
  computed_at       DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (cohort_id, metric_key),
  CONSTRAINT fk_cmb_cohort FOREIGN KEY (cohort_id) REFERENCES metric_cohorts(id) ON DELETE CASCADE,
  CONSTRAINT fk_cmb_def    FOREIGN KEY (metric_key) REFERENCES metric_definitions(metric_key)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

-- 05 Team Shape & Formation, Team Metrics, Formation Stability, Build-up/Defensive shapes.
CREATE TABLE team_shape_snapshots (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  video_id          CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  run_id            CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  team_side         ENUM('HOME','AWAY') NOT NULL,
  phase             ENUM('ALL','IN_POSSESSION','OUT_OF_POSSESSION','TRANSITION','SET_PIECE') NOT NULL,
  from_pts_us       BIGINT UNSIGNED NOT NULL,
  to_pts_us         BIGINT UNSIGNED NOT NULL,
  formation_code    VARCHAR(12) CHARACTER SET ascii NULL COMMENT '4-3-3 / 4-2-3-1 / 4-4-2',
  formation_confidence DECIMAL(5,4) NULL,
  avg_width_m       DECIMAL(5,2) NULL,
  avg_length_m      DECIMAL(5,2) NULL,
  def_line_height_m DECIMAL(5,2) NULL,
  compactness_m     DECIMAL(5,2) NULL,
  shape_variability ENUM('LOW','MEDIUM','HIGH') NULL,
  variability_series JSON NULL COMMENT 'Sparkline points',
  stability_pct     DECIMAL(5,2) NULL COMMENT 'Formation Stability',
  visible_players   TINYINT UNSIGNED NOT NULL COMMENT 'Shape is partial when < 10',
  calibration_id    CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  evidence_state    ENUM('DETECTED','INFERRED','CONFIRMED','NOT_MEASURED') NOT NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_tss_org_id (organization_id, id),
  KEY ix_tss_lookup (organization_id, video_id, team_side, phase, from_pts_us),
  CONSTRAINT fk_tss_video FOREIGN KEY (organization_id, video_id) REFERENCES video_sources(organization_id, id),
  CONSTRAINT fk_tss_run   FOREIGN KEY (organization_id, run_id) REFERENCES pipeline_runs(organization_id, id),
  CONSTRAINT fk_tss_cal   FOREIGN KEY (calibration_id) REFERENCES pitch_calibrations(id),
  CONSTRAINT ck_tss_range CHECK (to_pts_us > from_pts_us),
  CONSTRAINT ck_tss_metres CHECK (avg_width_m IS NULL OR calibration_id IS NOT NULL),
  CONSTRAINT ck_tss_nm CHECK (evidence_state <> 'NOT_MEASURED' OR (formation_code IS NULL AND avg_width_m IS NULL))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE team_shape_nodes (
  snapshot_id       CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  slot_no           TINYINT UNSIGNED NOT NULL,
  track_id          CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  player_id         CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'Node label shown only when identity CONFIRMED',
  avg_x_norm        DECIMAL(6,5) NOT NULL COMMENT '0..1 pitch length (attacking direction normalised)',
  avg_y_norm        DECIMAL(6,5) NOT NULL,
  role_line         ENUM('GK','DEF','MID','FWD') NULL,
  PRIMARY KEY (snapshot_id, slot_no),
  CONSTRAINT fk_tsn_snap   FOREIGN KEY (organization_id, snapshot_id) REFERENCES team_shape_snapshots(organization_id, id) ON DELETE CASCADE,
  CONSTRAINT fk_tsn_track  FOREIGN KEY (organization_id, track_id) REFERENCES tracks(organization_id, id),
  CONSTRAINT fk_tsn_player FOREIGN KEY (player_id) REFERENCES players(id),
  CONSTRAINT ck_tsn_xy CHECK (avg_x_norm BETWEEN 0 AND 1 AND avg_y_norm BETWEEN 0 AND 1)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

-- 05 Pass Network (nodes + weighted edges; 1-3 / 4-6 / 7-10 / 10+ buckets derived client-side from pass_count).
CREATE TABLE pass_networks (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  video_id          CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  team_side         ENUM('HOME','AWAY') NOT NULL,
  from_pts_us       BIGINT UNSIGNED NOT NULL,
  to_pts_us         BIGINT UNSIGNED NOT NULL,
  min_event_state   ENUM('DETECTED','INFERRED','CONFIRMED','NOT_MEASURED') NOT NULL DEFAULT 'INFERRED' COMMENT 'Lowest evidence admitted into the network',
  computed_at       DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (id),
  UNIQUE KEY uq_pn_org_id (organization_id, id),
  KEY ix_pn_lookup (organization_id, video_id, team_side, from_pts_us, to_pts_us),
  CONSTRAINT fk_pn_video FOREIGN KEY (organization_id, video_id) REFERENCES video_sources(organization_id, id),
  CONSTRAINT ck_pn_range CHECK (to_pts_us > from_pts_us)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE pass_network_nodes (
  network_id        CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  node_key          VARCHAR(40) CHARACTER SET ascii NOT NULL COMMENT 'player id or "UNKNOWN:<track>"',
  player_id         CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  track_id          CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  avg_x_norm        DECIMAL(6,5) NOT NULL,
  avg_y_norm        DECIMAL(6,5) NOT NULL,
  touches           INT UNSIGNED NOT NULL DEFAULT 0,
  PRIMARY KEY (network_id, node_key),
  CONSTRAINT fk_pnn_net    FOREIGN KEY (organization_id, network_id) REFERENCES pass_networks(organization_id, id) ON DELETE CASCADE,
  CONSTRAINT fk_pnn_player FOREIGN KEY (player_id) REFERENCES players(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE pass_network_edges (
  network_id        CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  from_node_key     VARCHAR(40) CHARACTER SET ascii NOT NULL,
  to_node_key       VARCHAR(40) CHARACTER SET ascii NOT NULL,
  pass_count        SMALLINT UNSIGNED NOT NULL,
  successful_count  SMALLINT UNSIGNED NOT NULL,
  PRIMARY KEY (network_id, from_node_key, to_node_key),
  CONSTRAINT fk_pne_from FOREIGN KEY (network_id, from_node_key) REFERENCES pass_network_nodes(network_id, node_key) ON DELETE CASCADE,
  CONSTRAINT fk_pne_to   FOREIGN KEY (network_id, to_node_key) REFERENCES pass_network_nodes(network_id, node_key) ON DELETE CASCADE,
  CONSTRAINT ck_pne CHECK (successful_count <= pass_count AND pass_count > 0 AND from_node_key <> to_node_key)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

-- Heat maps (05 Heat Zones per team; 04/08 player heatmaps, Touches, Territory). Grid stored inline when small.
CREATE TABLE heatmaps (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  video_id          CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  subject_kind      ENUM('PLAYER','TEAM') NOT NULL,
  player_id         CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  team_side         ENUM('HOME','AWAY') NULL,
  heatmap_kind      ENUM('POSITION','TOUCHES','TERRITORY','FINAL_THIRDS','PRESSING') NOT NULL,
  space             ENUM('PITCH','IMAGE') NOT NULL COMMENT 'IMAGE heatmaps must be labelled as on-screen, not pitch occupancy',
  period            ENUM('FULL','FIRST_HALF','SECOND_HALF') NOT NULL DEFAULT 'FULL',
  grid_cols         TINYINT UNSIGNED NOT NULL DEFAULT 24,
  grid_rows         TINYINT UNSIGNED NOT NULL DEFAULT 16,
  grid_values       JSON NULL COMMENT 'Row-major normalised densities 0..1',
  image_asset_id    CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  coverage_ratio    DECIMAL(5,4) NULL,
  evidence_state    ENUM('DETECTED','INFERRED','CONFIRMED','NOT_MEASURED') NOT NULL,
  computed_at       DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (id),
  KEY ix_hm_lookup (organization_id, video_id, subject_kind, player_id, team_side, heatmap_kind, period),
  CONSTRAINT fk_hm_video  FOREIGN KEY (organization_id, video_id) REFERENCES video_sources(organization_id, id),
  CONSTRAINT fk_hm_player FOREIGN KEY (player_id) REFERENCES players(id),
  CONSTRAINT fk_hm_img    FOREIGN KEY (organization_id, image_asset_id) REFERENCES assets(organization_id, id),
  CONSTRAINT ck_hm_subject CHECK ((subject_kind = 'PLAYER' AND player_id IS NOT NULL) OR (subject_kind = 'TEAM' AND team_side IS NOT NULL)),
  CONSTRAINT ck_hm_payload CHECK (evidence_state = 'NOT_MEASURED' OR grid_values IS NOT NULL OR image_asset_id IS NOT NULL),
  CONSTRAINT ck_hm_grid CHECK (grid_values IS NULL OR JSON_LENGTH(grid_values) = grid_cols * grid_rows)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE possession_episodes (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  video_id          CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  run_id            CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  team_side         ENUM('HOME','AWAY','UNKNOWN') NOT NULL,
  player_id         CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  start_pts_us      BIGINT UNSIGNED NOT NULL,
  end_pts_us        BIGINT UNSIGNED NOT NULL,
  confidence        DECIMAL(5,4) NULL,
  evidence_id       CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  PRIMARY KEY (id),
  KEY ix_pe_video (organization_id, video_id, start_pts_us),
  CONSTRAINT fk_pe_video FOREIGN KEY (organization_id, video_id) REFERENCES video_sources(organization_id, id),
  CONSTRAINT fk_pe_run   FOREIGN KEY (organization_id, run_id) REFERENCES pipeline_runs(organization_id, id),
  CONSTRAINT fk_pe_player FOREIGN KEY (player_id) REFERENCES players(id),
  CONSTRAINT ck_pe_range CHECK (end_pts_us > start_pts_us)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

-- 05 Off-Ball Runs (paths) and other movement classifications.
CREATE TABLE movement_segments (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  video_id          CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  track_id          CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  player_id         CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  start_pts_us      BIGINT UNSIGNED NOT NULL,
  end_pts_us        BIGINT UNSIGNED NOT NULL,
  movement_kind     ENUM('OFF_BALL_RUN','LEADING_RUN','SUPPORTING_RUN','PROGRESSIVE_RUN','RUN_INTO_BOX','SPRINT','CARRY','PRESS') NOT NULL,
  path_norm         JSON NULL COMMENT '[[x,y],...] normalised pitch coords for drawing',
  distance_m        DECIMAL(6,2) NULL,
  calibration_id    CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  confidence        DECIMAL(5,4) NULL,
  evidence_state    ENUM('DETECTED','INFERRED','CONFIRMED','NOT_MEASURED') NOT NULL,
  PRIMARY KEY (id),
  KEY ix_ms_player (organization_id, video_id, player_id, movement_kind, start_pts_us),
  CONSTRAINT fk_ms_track  FOREIGN KEY (organization_id, track_id) REFERENCES tracks(organization_id, id),
  CONSTRAINT fk_ms_video  FOREIGN KEY (organization_id, video_id) REFERENCES video_sources(organization_id, id),
  CONSTRAINT fk_ms_player FOREIGN KEY (player_id) REFERENCES players(id),
  CONSTRAINT fk_ms_cal    FOREIGN KEY (calibration_id) REFERENCES pitch_calibrations(id),
  CONSTRAINT ck_ms_range  CHECK (end_pts_us > start_pts_us),
  CONSTRAINT ck_ms_metres CHECK (distance_m IS NULL OR calibration_id IS NOT NULL)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE tactical_windows (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  video_id          CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  run_id            CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  kind              ENUM('PRESSING','BUILD_UP','TRANSITION','SET_PIECE','DEFENSIVE_BLOCK') NOT NULL,
  team_side         ENUM('HOME','AWAY') NOT NULL,
  from_pts_us       BIGINT UNSIGNED NOT NULL,
  to_pts_us         BIGINT UNSIGNED NOT NULL,
  coverage_ratio    DECIMAL(5,4) NOT NULL,
  metrics           JSON NOT NULL COMMENT 'e.g. PPDA, regains, press height for 05 Pressing Map',
  evidence_state    ENUM('DETECTED','INFERRED','CONFIRMED','NOT_MEASURED') NOT NULL,
  evidence_id       CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  PRIMARY KEY (id),
  KEY ix_tw (organization_id, video_id, kind, team_side, from_pts_us),
  CONSTRAINT fk_tw_video FOREIGN KEY (organization_id, video_id) REFERENCES video_sources(organization_id, id),
  CONSTRAINT fk_tw_run   FOREIGN KEY (organization_id, run_id) REFERENCES pipeline_runs(organization_id, id),
  CONSTRAINT ck_tw_range CHECK (to_pts_us > from_pts_us AND coverage_ratio BETWEEN 0 AND 1)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

-- ===== 007_reels_spotlight_studio.sql =====
-- Migration 007 — Reel Builder (06), Clip Studio (07), media bin clips, timeline, captions, chapters, revisions
USE `otsi_owner_vie`;

CREATE TABLE music_tracks (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  owner_organization_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'NULL = platform-licensed library',
  title             VARCHAR(150) NOT NULL COMMENT 'Music select "Epic Cinematic"',
  mood              VARCHAR(40) NULL,
  bpm               SMALLINT UNSIGNED NULL,
  duration_us       BIGINT UNSIGNED NOT NULL,
  audio_asset_id    CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  waveform_asset_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  license_ref       VARCHAR(255) NOT NULL,
  allowed_uses      JSON NOT NULL DEFAULT (JSON_ARRAY('INTERNAL','EXPORT')),
  is_active         BOOLEAN NOT NULL DEFAULT TRUE,
  PRIMARY KEY (id),
  CONSTRAINT fk_music_owner FOREIGN KEY (owner_organization_id) REFERENCES organizations(id),
  CONSTRAINT fk_music_audio FOREIGN KEY (audio_asset_id) REFERENCES assets(id),
  CONSTRAINT fk_music_wave  FOREIGN KEY (waveform_asset_id) REFERENCES assets(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE brand_kits (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  name              VARCHAR(100) NOT NULL COMMENT '10 Branded Overlays logo select ("OTSI VIE")',
  logo_asset_id     CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  watermark_asset_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  intro_asset_id    CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  outro_asset_id    CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT '"End Screen" / Custom Intro/Outro',
  primary_color_hex CHAR(7) CHARACTER SET ascii NULL,
  font_asset_id     CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  is_default        BOOLEAN NOT NULL DEFAULT FALSE,
  created_at        DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (id),
  UNIQUE KEY uq_brand_kits_org_id (organization_id, id),
  UNIQUE KEY uq_brand_kits_name (organization_id, name),
  CONSTRAINT fk_bk_org   FOREIGN KEY (organization_id) REFERENCES organizations(id),
  CONSTRAINT fk_bk_logo  FOREIGN KEY (organization_id, logo_asset_id) REFERENCES assets(organization_id, id),
  CONSTRAINT fk_bk_wm    FOREIGN KEY (organization_id, watermark_asset_id) REFERENCES assets(organization_id, id),
  CONSTRAINT fk_bk_intro FOREIGN KEY (organization_id, intro_asset_id) REFERENCES assets(organization_id, id),
  CONSTRAINT fk_bk_outro FOREIGN KEY (organization_id, outro_asset_id) REFERENCES assets(organization_id, id),
  CONSTRAINT fk_bk_font  FOREIGN KEY (organization_id, font_asset_id) REFERENCES assets(organization_id, id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE effect_presets (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  owner_organization_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  name              VARCHAR(100) NOT NULL,
  effect_family     ENUM('SPOTLIGHT','TRANSITION','GRAPHIC','LOWER_THIRD','STAT_CARD','CAPTION_STYLE','COLOR','SPEED','TRANSFORM') NOT NULL,
  version           VARCHAR(20) NOT NULL,
  schema_version    VARCHAR(20) NOT NULL,
  config            JSON NOT NULL,
  created_at        DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  owner_key         CHAR(36) CHARACTER SET ascii COLLATE ascii_bin AS (COALESCE(owner_organization_id, 'GLOBAL')) STORED,
  PRIMARY KEY (id),
  UNIQUE KEY uq_effect_presets (owner_key, name, version),
  CONSTRAINT fk_ep_owner FOREIGN KEY (owner_organization_id) REFERENCES organizations(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='Transitions Fade/Zoom/Spin/Dissolve; graphics Spotlight Circle/Pass Trajectory/Player Highlight/Team Logo ...';

CREATE TABLE reel_projects (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  project_id        CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  video_id          CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'Primary source; clips may come from several videos',
  match_id          CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  reel_kind         ENUM('SPOTLIGHT','HIGHLIGHTS','TACTICAL','CUSTOM') NOT NULL DEFAULT 'SPOTLIGHT',
  title             VARCHAR(200) NOT NULL COMMENT 'Reel Info Title',
  description       VARCHAR(2000) NULL COMMENT 'Reel Info Description (optional)',
  reel_type_label   VARCHAR(80) NULL COMMENT 'e.g. "Progressive Passes" subtitle on cards/summary',
  wizard_step       ENUM('SELECT_PLAYER','CHOOSE_MOMENTS','EDIT_STYLE','EXPORT') NOT NULL DEFAULT 'SELECT_PLAYER',
  aspect_ratio      ENUM('16:9','9:16','1:1','4:5') NOT NULL DEFAULT '16:9',
  duration_mode     ENUM('AUTO_BEST','FIXED_30S','FIXED_60S','FIXED_90S','FIXED_120S','CUSTOM') NOT NULL DEFAULT 'AUTO_BEST',
  target_duration_us BIGINT UNSIGNED NULL,
  music_track_id    CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  brand_kit_id      CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  status            ENUM('DRAFT','REVIEW_REQUIRED','READY_TO_RENDER','RENDERING','QC','READY','PUBLISHED','BLOCKED','FAILED','ARCHIVED') NOT NULL DEFAULT 'DRAFT',
  blocked_reason    VARCHAR(64) CHARACTER SET ascii NULL COMMENT 'IDENTITY_UNRESOLVED, RIGHTS_BLOCKED ...',
  current_revision  INT UNSIGNED NOT NULL DEFAULT 0,
  sequence_duration_us BIGINT UNSIGNED NOT NULL DEFAULT 0 COMMENT 'Total timeline length "01:28.00"',
  created_by        CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  created_at        DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at        DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  row_version       BIGINT UNSIGNED NOT NULL DEFAULT 1,
  PRIMARY KEY (id),
  UNIQUE KEY uq_reels_org_id (organization_id, id),
  KEY ix_reels_org_status (organization_id, status, updated_at),
  KEY ix_reels_project (organization_id, project_id),
  CONSTRAINT fk_reels_project FOREIGN KEY (organization_id, project_id) REFERENCES projects(organization_id, id),
  CONSTRAINT fk_reels_video   FOREIGN KEY (organization_id, video_id) REFERENCES video_sources(organization_id, id),
  CONSTRAINT fk_reels_match   FOREIGN KEY (organization_id, match_id) REFERENCES matches(organization_id, id),
  CONSTRAINT fk_reels_music   FOREIGN KEY (music_track_id) REFERENCES music_tracks(id),
  CONSTRAINT fk_reels_brand   FOREIGN KEY (organization_id, brand_kit_id) REFERENCES brand_kits(organization_id, id),
  CONSTRAINT fk_reels_user    FOREIGN KEY (created_by) REFERENCES users(id),
  CONSTRAINT ck_reels_blocked CHECK (status <> 'BLOCKED' OR blocked_reason IS NOT NULL)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

-- 06 right panel: Spotlight Controls, Player Targeting, Overlays, Branding. One row per reel; validated ranges.
CREATE TABLE reel_style_settings (
  reel_id           CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  spotlight_intensity_pct TINYINT UNSIGNED NOT NULL DEFAULT 85,
  ray_width_pct     TINYINT UNSIGNED NOT NULL DEFAULT 60,
  vignette_strength_pct TINYINT UNSIGNED NOT NULL DEFAULT 45,
  glow_amount_pct   TINYINT UNSIGNED NOT NULL DEFAULT 55,
  target_lock_sensitivity_pct TINYINT UNSIGNED NOT NULL DEFAULT 72,
  auto_track_player BOOLEAN NOT NULL DEFAULT TRUE,
  overlay_player_info_card BOOLEAN NOT NULL DEFAULT TRUE,
  overlay_match_score_time BOOLEAN NOT NULL DEFAULT TRUE,
  overlay_competition_logo BOOLEAN NOT NULL DEFAULT TRUE COMMENT 'Requires competitions.logo_license_ref at render',
  overlay_lower_third BOOLEAN NOT NULL DEFAULT TRUE,
  use_watermark     BOOLEAN NOT NULL DEFAULT TRUE,
  custom_logo       BOOLEAN NOT NULL DEFAULT FALSE,
  end_screen        BOOLEAN NOT NULL DEFAULT TRUE,
  spotlight_preset_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  updated_at        DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  PRIMARY KEY (reel_id),
  CONSTRAINT fk_rss_reel   FOREIGN KEY (organization_id, reel_id) REFERENCES reel_projects(organization_id, id) ON DELETE CASCADE,
  CONSTRAINT fk_rss_preset FOREIGN KEY (spotlight_preset_id) REFERENCES effect_presets(id),
  CONSTRAINT ck_rss_ranges CHECK (spotlight_intensity_pct <= 100 AND ray_width_pct <= 100 AND vignette_strength_pct <= 100
                                  AND glow_amount_pct <= 100 AND target_lock_sensitivity_pct <= 100)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE reel_targets (
  reel_id           CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  player_id         CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT '"Lock on confirmed player" — must be a canonical player',
  primary_track_id  CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  identity_decision_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'CONFIRMED decision that authorises the lock',
  is_primary        BOOLEAN NOT NULL DEFAULT TRUE,
  added_at          DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (reel_id, player_id),
  CONSTRAINT fk_rt_reel   FOREIGN KEY (organization_id, reel_id) REFERENCES reel_projects(organization_id, id) ON DELETE CASCADE,
  CONSTRAINT fk_rt_player FOREIGN KEY (player_id) REFERENCES players(id),
  CONSTRAINT fk_rt_track  FOREIGN KEY (organization_id, primary_track_id) REFERENCES tracks(organization_id, id),
  CONSTRAINT fk_rt_dec    FOREIGN KEY (organization_id, identity_decision_id) REFERENCES track_identity_decisions(organization_id, id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

-- 06 Suggested Key Moments (ranked; header count = COUNT where status<>'DISMISSED').
CREATE TABLE moment_suggestions (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  reel_id           CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  event_id          CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  video_id          CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  in_pts_us         BIGINT UNSIGNED NOT NULL,
  out_pts_us        BIGINT UNSIGNED NOT NULL,
  title             VARCHAR(80) NOT NULL COMMENT 'Card title e.g. "Progressive Pass"',
  rank_no           SMALLINT UNSIGNED NOT NULL COMMENT 'Card number badge',
  score             DECIMAL(5,4) NOT NULL,
  thumbnail_asset_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  status            ENUM('SUGGESTED','SELECTED','DISMISSED') NOT NULL DEFAULT 'SUGGESTED' COMMENT 'Checkbox badge',
  model_version_id  CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  created_at        DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (id),
  UNIQUE KEY uq_ms_rank (reel_id, rank_no),
  KEY ix_ms_reel (organization_id, reel_id, status, rank_no),
  CONSTRAINT fk_mom_reel  FOREIGN KEY (organization_id, reel_id) REFERENCES reel_projects(organization_id, id) ON DELETE CASCADE,
  CONSTRAINT fk_mom_event FOREIGN KEY (organization_id, event_id) REFERENCES event_candidates(organization_id, id),
  CONSTRAINT fk_mom_video FOREIGN KEY (organization_id, video_id) REFERENCES video_sources(organization_id, id),
  CONSTRAINT fk_mom_thumb FOREIGN KEY (organization_id, thumbnail_asset_id) REFERENCES assets(organization_id, id),
  CONSTRAINT fk_mom_model FOREIGN KEY (model_version_id) REFERENCES model_versions(id),
  CONSTRAINT ck_mom_range CHECK (out_pts_us > in_pts_us AND score BETWEEN 0 AND 1)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

-- 07 Media Bin clips (sub-clips of a source video) and the Clip Inspector metadata.
CREATE TABLE media_clips (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  folder_id         CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'Media Bin breadcrumb location',
  source_video_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  in_pts_us         BIGINT UNSIGNED NOT NULL,
  out_pts_us        BIGINT UNSIGNED NOT NULL,
  duration_us       BIGINT UNSIGNED AS (out_pts_us - in_pts_us) STORED COMMENT 'Clip duration chip',
  clip_asset_id     CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'Optional pre-cut file (name shown, e.g. *.mp4)',
  thumbnail_asset_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  display_name      VARCHAR(255) NOT NULL COMMENT 'Inspector title / timeline label',
  player_id         CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'Inspector Player (confirmed only)',
  match_id          CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'Inspector Match',
  event_id          CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  event_type        VARCHAR(32) CHARACTER SET ascii NULL COMMENT 'Inspector Event Type',
  match_clock_ms    INT UNSIGNED NULL COMMENT 'Inspector Timestamp',
  period            ENUM('FIRST_HALF','SECOND_HALF','ET_FIRST','ET_SECOND') NULL COMMENT '"(2nd Half)"',
  notes             VARCHAR(2000) NULL COMMENT 'Inspector Notes',
  created_by        CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  created_at        DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT '"Added 16 Apr 2024, 14:32"',
  updated_at        DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  PRIMARY KEY (id),
  UNIQUE KEY uq_media_clips_org_id (organization_id, id),
  KEY ix_mc_folder (organization_id, folder_id, created_at),
  KEY ix_mc_player (organization_id, player_id),
  FULLTEXT KEY ft_mc_search (display_name, notes),
  CONSTRAINT fk_mc_folder FOREIGN KEY (organization_id, folder_id) REFERENCES folders(organization_id, id),
  CONSTRAINT fk_mc_video  FOREIGN KEY (organization_id, source_video_id) REFERENCES video_sources(organization_id, id),
  CONSTRAINT fk_mc_asset  FOREIGN KEY (organization_id, clip_asset_id) REFERENCES assets(organization_id, id),
  CONSTRAINT fk_mc_thumb  FOREIGN KEY (organization_id, thumbnail_asset_id) REFERENCES assets(organization_id, id),
  CONSTRAINT fk_mc_player FOREIGN KEY (player_id) REFERENCES players(id),
  CONSTRAINT fk_mc_match  FOREIGN KEY (organization_id, match_id) REFERENCES matches(organization_id, id),
  CONSTRAINT fk_mc_event  FOREIGN KEY (organization_id, event_id) REFERENCES event_candidates(organization_id, id),
  CONSTRAINT fk_mc_etype  FOREIGN KEY (event_type) REFERENCES event_types(code),
  CONSTRAINT fk_mc_user   FOREIGN KEY (created_by) REFERENCES users(id),
  CONSTRAINT ck_mc_range  CHECK (out_pts_us > in_pts_us)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE media_clip_tags (
  clip_id           CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  tag_id            CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  PRIMARY KEY (clip_id, tag_id),
  CONSTRAINT fk_mct_clip FOREIGN KEY (organization_id, clip_id) REFERENCES media_clips(organization_id, id) ON DELETE CASCADE,
  CONSTRAINT fk_mct_tag  FOREIGN KEY (organization_id, tag_id) REFERENCES tags(organization_id, id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='Inspector Tags chips (Pass / Progressive / Build-up) + "+" add';

CREATE TABLE reel_clips (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  reel_id           CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  media_clip_id     CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  moment_suggestion_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  source_video_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  in_pts_us         BIGINT UNSIGNED NOT NULL,
  out_pts_us        BIGINT UNSIGNED NOT NULL,
  sequence_index    SMALLINT UNSIGNED NOT NULL,
  playback_speed    DECIMAL(6,3) NOT NULL DEFAULT 1.000,
  output_duration_us BIGINT UNSIGNED AS (CAST((out_pts_us - in_pts_us) / playback_speed AS UNSIGNED)) STORED,
  source_event_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  review_state      ENUM('PENDING','APPROVED','REJECTED','RED') NOT NULL DEFAULT 'PENDING',
  target_identity_verified BOOLEAN NOT NULL DEFAULT FALSE COMMENT 'Target CONFIRMED across [in,out]; render blocks otherwise',
  PRIMARY KEY (id),
  UNIQUE KEY uq_reel_clips_org_id (organization_id, id),
  UNIQUE KEY uq_reel_clips_seq (reel_id, sequence_index),
  CONSTRAINT fk_rc_reel   FOREIGN KEY (organization_id, reel_id) REFERENCES reel_projects(organization_id, id) ON DELETE CASCADE,
  CONSTRAINT fk_rc_mclip  FOREIGN KEY (organization_id, media_clip_id) REFERENCES media_clips(organization_id, id),
  CONSTRAINT fk_rc_moment FOREIGN KEY (moment_suggestion_id) REFERENCES moment_suggestions(id),
  CONSTRAINT fk_rc_video  FOREIGN KEY (organization_id, source_video_id) REFERENCES video_sources(organization_id, id),
  CONSTRAINT fk_rc_event  FOREIGN KEY (organization_id, source_event_id) REFERENCES event_candidates(organization_id, id),
  CONSTRAINT ck_rc_range  CHECK (out_pts_us > in_pts_us),
  CONSTRAINT ck_rc_speed  CHECK (playback_speed BETWEEN 0.1 AND 8)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE timeline_tracks (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  reel_id           CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  track_type        ENUM('VIDEO','SPOTLIGHT','TRANSITION','GRAPHICS','TEXT_OVERLAY','LOWER_THIRD','CAPTIONS','STATISTICS','SOUNDTRACK','AUDIO_FX','VOICEOVER') NOT NULL,
  label             VARCHAR(40) NOT NULL COMMENT '07 track header labels; 06 "Video Clips / Spotlight Effects / Text & Overlays / Audio"',
  layer             TINYINT UNSIGNED NOT NULL,
  is_visible        BOOLEAN NOT NULL DEFAULT TRUE COMMENT 'Eye icon',
  is_locked         BOOLEAN NOT NULL DEFAULT FALSE COMMENT 'Lock icon',
  is_muted          BOOLEAN NOT NULL DEFAULT FALSE COMMENT 'Mute icon (audio tracks)',
  PRIMARY KEY (id),
  UNIQUE KEY uq_tt_org_id (organization_id, id),
  UNIQUE KEY uq_tt_layer (reel_id, layer),
  CONSTRAINT fk_tt_reel FOREIGN KEY (organization_id, reel_id) REFERENCES reel_projects(organization_id, id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE timeline_items (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  timeline_track_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  reel_clip_id      CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  item_kind         ENUM('CLIP','TRANSITION','GRAPHIC','TEXT','LOWER_THIRD','CAPTION','STAT','AUDIO','SPOTLIGHT') NOT NULL,
  label             VARCHAR(200) NULL COMMENT 'Bar label e.g. "Fade", "Stat Card", "Pass Distance (7.4 km)"',
  start_us          BIGINT UNSIGNED NOT NULL,
  duration_us       BIGINT UNSIGNED NOT NULL,
  end_us            BIGINT UNSIGNED AS (start_us + duration_us) STORED,
  effect_preset_id  CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  asset_id          CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  metric_value_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'STAT items must bind to a real metric (never typed numbers)',
  parameters        JSON NOT NULL DEFAULT (JSON_OBJECT()),
  PRIMARY KEY (id),
  UNIQUE KEY uq_ti_org_id (organization_id, id),
  KEY ix_ti_track_time (timeline_track_id, start_us),
  CONSTRAINT fk_ti_track  FOREIGN KEY (organization_id, timeline_track_id) REFERENCES timeline_tracks(organization_id, id) ON DELETE CASCADE,
  CONSTRAINT fk_ti_clip   FOREIGN KEY (organization_id, reel_clip_id) REFERENCES reel_clips(organization_id, id),
  CONSTRAINT fk_ti_preset FOREIGN KEY (effect_preset_id) REFERENCES effect_presets(id),
  CONSTRAINT fk_ti_asset  FOREIGN KEY (asset_id) REFERENCES assets(id),
  CONSTRAINT fk_ti_metric FOREIGN KEY (metric_value_id) REFERENCES metric_values(id),
  CONSTRAINT ck_ti_dur    CHECK (duration_us > 0),
  CONSTRAINT ck_ti_clip   CHECK (item_kind <> 'CLIP' OR reel_clip_id IS NOT NULL),
  CONSTRAINT ck_ti_stat   CHECK (item_kind <> 'STAT' OR metric_value_id IS NOT NULL)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE effect_keyframes (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  timeline_item_id  CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  time_offset_us    BIGINT UNSIGNED NOT NULL,
  property_name     VARCHAR(48) CHARACTER SET ascii NOT NULL,
  value             JSON NOT NULL,
  interpolation     ENUM('HOLD','LINEAR','EASE_IN_OUT') NOT NULL DEFAULT 'LINEAR',
  PRIMARY KEY (id),
  UNIQUE KEY uq_ek (timeline_item_id, time_offset_us, property_name),
  CONSTRAINT fk_ek_item FOREIGN KEY (timeline_item_id) REFERENCES timeline_items(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE caption_cues (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  timeline_item_id  CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  start_us          BIGINT UNSIGNED NOT NULL,
  end_us            BIGINT UNSIGNED NOT NULL,
  text              VARCHAR(500) NOT NULL,
  language          VARCHAR(16) NOT NULL DEFAULT 'en',
  source            ENUM('MANUAL','AUTO_ASR','AUTO_TEMPLATE') NOT NULL,
  PRIMARY KEY (id),
  KEY ix_cc_item (timeline_item_id, start_us),
  CONSTRAINT fk_cc_item FOREIGN KEY (timeline_item_id) REFERENCES timeline_items(id) ON DELETE CASCADE,
  CONSTRAINT ck_cc_range CHECK (end_us > start_us)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

-- Saved revisions (Save Project). Undo/Redo is client-side within a session; server keeps immutable snapshots.
CREATE TABLE reel_revisions (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  reel_id           CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  revision_no       INT UNSIGNED NOT NULL,
  timeline_snapshot JSON NOT NULL,
  snapshot_sha256   CHAR(64) CHARACTER SET ascii NOT NULL,
  saved_by          CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  saved_at          DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  note              VARCHAR(255) NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_rr_org_id (organization_id, id),
  UNIQUE KEY uq_rr_no (reel_id, revision_no),
  CONSTRAINT fk_rr_reel FOREIGN KEY (organization_id, reel_id) REFERENCES reel_projects(organization_id, id) ON DELETE CASCADE,
  CONSTRAINT fk_rr_user FOREIGN KEY (saved_by) REFERENCES users(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

-- 10 Highlight Chapters (Auto Chapters toggle; Edit Chapters).
CREATE TABLE reel_chapters (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  reel_id           CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  chapter_no        SMALLINT UNSIGNED NOT NULL,
  title             VARCHAR(80) NOT NULL COMMENT 'Intro, Build Up Play, Progressive Passes ...',
  start_us          BIGINT UNSIGNED NOT NULL,
  duration_us       BIGINT UNSIGNED NOT NULL,
  thumbnail_asset_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  source            ENUM('AUTO','MANUAL') NOT NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_rch_no (reel_id, chapter_no),
  CONSTRAINT fk_rch_reel  FOREIGN KEY (organization_id, reel_id) REFERENCES reel_projects(organization_id, id) ON DELETE CASCADE,
  CONSTRAINT fk_rch_thumb FOREIGN KEY (organization_id, thumbnail_asset_id) REFERENCES assets(organization_id, id),
  CONSTRAINT ck_rch_dur   CHECK (duration_us > 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE reel_settings_flags (
  reel_id           CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  auto_chapters     BOOLEAN NOT NULL DEFAULT TRUE,
  PRIMARY KEY (reel_id),
  CONSTRAINT fk_rsf_reel FOREIGN KEY (organization_id, reel_id) REFERENCES reel_projects(organization_id, id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

-- ===== 008_reports_scouting.sql =====
-- Migration 008 — Player Report (08): reports, frozen KPI snapshots, role profile, AI insights, scouting, dossiers
USE `otsi_owner_vie`;

CREATE TABLE reports (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  project_id        CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  report_type       ENUM('PLAYER','MATCH','TEAM','SCOUTING_PACK') NOT NULL,
  player_id         CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  match_id          CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  video_id          CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  title             VARCHAR(200) NOT NULL,
  scope_kind        ENUM('MATCH','SEASON','RANGE') NOT NULL DEFAULT 'MATCH',
  scope_from        DATE NULL,
  scope_to          DATE NULL,
  cohort_id         CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'Comparison select',
  status            ENUM('DRAFT','GENERATED','REVIEW_REQUIRED','READY','PUBLISHED','ARCHIVED') NOT NULL DEFAULT 'DRAFT',
  published_by      CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  published_at      DATETIME(6) NULL,
  created_by        CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  created_at        DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at        DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  row_version       BIGINT UNSIGNED NOT NULL DEFAULT 1,
  PRIMARY KEY (id),
  UNIQUE KEY uq_reports_org_id (organization_id, id),
  KEY ix_reports_player (organization_id, player_id, status, updated_at),
  CONSTRAINT fk_rep_project FOREIGN KEY (organization_id, project_id) REFERENCES projects(organization_id, id),
  CONSTRAINT fk_rep_player  FOREIGN KEY (player_id) REFERENCES players(id),
  CONSTRAINT fk_rep_match   FOREIGN KEY (organization_id, match_id) REFERENCES matches(organization_id, id),
  CONSTRAINT fk_rep_video   FOREIGN KEY (organization_id, video_id) REFERENCES video_sources(organization_id, id),
  CONSTRAINT fk_rep_cohort  FOREIGN KEY (cohort_id) REFERENCES metric_cohorts(id),
  CONSTRAINT fk_rep_pub     FOREIGN KEY (published_by) REFERENCES users(id),
  CONSTRAINT fk_rep_user    FOREIGN KEY (created_by) REFERENCES users(id),
  CONSTRAINT ck_rep_player  CHECK (report_type <> 'PLAYER' OR player_id IS NOT NULL),
  CONSTRAINT ck_rep_pub     CHECK (status <> 'PUBLISHED' OR (published_by IS NOT NULL AND published_at IS NOT NULL)),
  CONSTRAINT ck_rep_range   CHECK (scope_to IS NULL OR scope_from IS NULL OR scope_to >= scope_from)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

-- Values shown in a report are FROZEN at generation so a published PDF never changes under the reader.
CREATE TABLE report_metric_snapshots (
  report_id         CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  block             ENUM('KPI_TILE','COMPARISON','BIO','CONFIDENCE','HEATMAP','ACTION_MAP','OTHER') NOT NULL,
  metric_key        VARCHAR(48) CHARACTER SET ascii NOT NULL,
  display_order     TINYINT UNSIGNED NOT NULL,
  source_metric_value_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  value_numeric     DOUBLE NULL,
  value_per90       DOUBLE NULL,
  delta_pct         DOUBLE NULL COMMENT 'KPI "↑ +8%" (NULL => hidden)',
  delta_abs         DOUBLE NULL COMMENT 'xG/xA "↑ +0.18"',
  cohort_value      DOUBLE NULL COMMENT 'Comparison grey bar / right value',
  coverage_ratio    DECIMAL(5,4) NULL,
  evidence_state    ENUM('DETECTED','INFERRED','CONFIRMED','NOT_MEASURED') NOT NULL,
  PRIMARY KEY (report_id, block, metric_key),
  CONSTRAINT fk_rms_report FOREIGN KEY (organization_id, report_id) REFERENCES reports(organization_id, id) ON DELETE CASCADE,
  CONSTRAINT fk_rms_def    FOREIGN KEY (metric_key) REFERENCES metric_definitions(metric_key),
  CONSTRAINT fk_rms_src    FOREIGN KEY (source_metric_value_id) REFERENCES metric_values(id),
  CONSTRAINT ck_rms_nm     CHECK (evidence_state <> 'NOT_MEASURED' OR value_numeric IS NULL)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE report_identity_confidence (
  report_id         CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  tracking_coverage_ratio DECIMAL(5,4) NULL COMMENT 'Ring value (task: track coverage)',
  identity_state    ENUM('UNRESOLVED','CANDIDATE','CONFIRMED','REJECTED','CONFLICT') NOT NULL COMMENT 'Pill: Unverified / Verified',
  observed_minutes  DECIMAL(7,2) NULL COMMENT '"across N minutes"',
  quality_band      ENUM('EXCELLENT','GOOD','FAIR','POOR','NOT_MEASURED') NOT NULL DEFAULT 'NOT_MEASURED',
  computed_at       DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (report_id),
  CONSTRAINT fk_ric_report FOREIGN KEY (organization_id, report_id) REFERENCES reports(organization_id, id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='08 Tracking Confidence card — separate per task, never one blended %';

CREATE TABLE player_role_profiles (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  player_id         CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  report_id         CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  role_title        VARCHAR(120) NOT NULL COMMENT '"Advanced Midfielder (Right Half-Space)"',
  summary           VARCHAR(1000) NOT NULL,
  author_kind       ENUM('ANALYST','AI_DRAFT') NOT NULL,
  approved_by       CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  approved_at       DATETIME(6) NULL,
  created_by        CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  created_at        DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (id),
  UNIQUE KEY uq_prp_org_id (organization_id, id),
  KEY ix_prp_player (organization_id, player_id, created_at),
  CONSTRAINT fk_prp_player FOREIGN KEY (player_id) REFERENCES players(id),
  CONSTRAINT fk_prp_report FOREIGN KEY (organization_id, report_id) REFERENCES reports(organization_id, id),
  CONSTRAINT fk_prp_appr   FOREIGN KEY (approved_by) REFERENCES users(id),
  CONSTRAINT fk_prp_user   FOREIGN KEY (created_by) REFERENCES users(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE player_role_traits (
  profile_id        CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  trait_label       VARCHAR(40) NOT NULL COMMENT 'Chips: Playmaker, Chance Creator ...',
  display_order     TINYINT UNSIGNED NOT NULL,
  PRIMARY KEY (profile_id, trait_label),
  CONSTRAINT fk_prt_profile FOREIGN KEY (organization_id, profile_id) REFERENCES player_role_profiles(organization_id, id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

-- 08 Generated Insights: AI text MUST cite the metric/event evidence it is based on.
CREATE TABLE report_insights (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  report_id         CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  display_order     TINYINT UNSIGNED NOT NULL,
  icon_key          VARCHAR(16) CHARACTER SET ascii NOT NULL COMMENT 'trend / pick / tgt / shld',
  accent_color_hex  CHAR(7) CHARACTER SET ascii NOT NULL,
  headline          VARCHAR(80) NOT NULL,
  body              VARCHAR(600) NOT NULL,
  model_version_id  CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  prompt_version    VARCHAR(20) NOT NULL,
  review_state      ENUM('AI_DRAFT','APPROVED','REJECTED') NOT NULL DEFAULT 'AI_DRAFT',
  reviewed_by       CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  created_at        DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (id),
  UNIQUE KEY uq_ri_org_id (organization_id, id),
  UNIQUE KEY uq_ri_order (report_id, display_order),
  CONSTRAINT fk_ri_report FOREIGN KEY (organization_id, report_id) REFERENCES reports(organization_id, id) ON DELETE CASCADE,
  CONSTRAINT fk_ri_model  FOREIGN KEY (model_version_id) REFERENCES model_versions(id),
  CONSTRAINT fk_ri_user   FOREIGN KEY (reviewed_by) REFERENCES users(id),
  CONSTRAINT ck_ri_review CHECK (review_state = 'AI_DRAFT' OR reviewed_by IS NOT NULL)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE report_insight_citations (
  insight_id        CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  citation_no       TINYINT UNSIGNED NOT NULL,
  metric_value_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  event_id          CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  cohort_id         CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  PRIMARY KEY (insight_id, citation_no),
  CONSTRAINT fk_ric_insight FOREIGN KEY (organization_id, insight_id) REFERENCES report_insights(organization_id, id) ON DELETE CASCADE,
  CONSTRAINT fk_ric_metric  FOREIGN KEY (metric_value_id) REFERENCES metric_values(id),
  CONSTRAINT fk_ric_event   FOREIGN KEY (organization_id, event_id) REFERENCES event_candidates(organization_id, id),
  CONSTRAINT fk_ric_cohort  FOREIGN KEY (cohort_id) REFERENCES metric_cohorts(id),
  CONSTRAINT ck_ric_one     CHECK (metric_value_id IS NOT NULL OR event_id IS NOT NULL OR cohort_id IS NOT NULL)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE scouting_assessments (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  player_id         CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  report_id         CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  overall_rating    DECIMAL(3,1) NULL COMMENT 'Overall Rating ring "x / 10"',
  rating_scale_max  TINYINT UNSIGNED NOT NULL DEFAULT 10,
  summary_quote     VARCHAR(600) NULL,
  status            ENUM('DRAFT','SUBMITTED','VERIFIED','ARCHIVED') NOT NULL DEFAULT 'DRAFT' COMMENT 'Footer "Awaiting verified scouting data" until VERIFIED',
  scout_user_id     CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  verified_by       CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  verified_at       DATETIME(6) NULL,
  created_at        DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  updated_at        DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
  PRIMARY KEY (id),
  UNIQUE KEY uq_sa_org_id (organization_id, id),
  KEY ix_sa_player (organization_id, player_id, status, created_at),
  CONSTRAINT fk_sa_player FOREIGN KEY (player_id) REFERENCES players(id),
  CONSTRAINT fk_sa_report FOREIGN KEY (organization_id, report_id) REFERENCES reports(organization_id, id),
  CONSTRAINT fk_sa_scout  FOREIGN KEY (organization_id, scout_user_id) REFERENCES memberships(organization_id, user_id),
  CONSTRAINT fk_sa_ver    FOREIGN KEY (verified_by) REFERENCES users(id),
  CONSTRAINT ck_sa_rating CHECK (overall_rating IS NULL OR overall_rating BETWEEN 0 AND rating_scale_max),
  CONSTRAINT ck_sa_verified CHECK (status <> 'VERIFIED' OR (verified_by IS NOT NULL AND verified_by <> scout_user_id))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE scouting_strengths (
  assessment_id     CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  display_order     TINYINT UNSIGNED NOT NULL,
  kind              ENUM('STRENGTH','DEVELOPMENT_AREA','RISK') NOT NULL DEFAULT 'STRENGTH',
  text              VARCHAR(120) NOT NULL COMMENT 'Green-check bullet lines',
  PRIMARY KEY (assessment_id, display_order),
  CONSTRAINT fk_sst_assessment FOREIGN KEY (organization_id, assessment_id) REFERENCES scouting_assessments(organization_id, id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE scouting_dossiers (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  folder_id         CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  name              VARCHAR(150) NOT NULL,
  created_by        CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  created_at        DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (id),
  UNIQUE KEY uq_sd_org_id (organization_id, id),
  CONSTRAINT fk_sd_folder FOREIGN KEY (organization_id, folder_id) REFERENCES folders(organization_id, id),
  CONSTRAINT fk_sd_user   FOREIGN KEY (created_by) REFERENCES users(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE scouting_dossier_items (
  dossier_id        CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  player_id         CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  report_id         CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  added_by          CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  added_at          DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (dossier_id, player_id),
  CONSTRAINT fk_sdi_dossier FOREIGN KEY (organization_id, dossier_id) REFERENCES scouting_dossiers(organization_id, id) ON DELETE CASCADE,
  CONSTRAINT fk_sdi_player  FOREIGN KEY (player_id) REFERENCES players(id),
  CONSTRAINT fk_sdi_report  FOREIGN KEY (organization_id, report_id) REFERENCES reports(organization_id, id),
  CONSTRAINT fk_sdi_user    FOREIGN KEY (added_by) REFERENCES users(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='08 "Add to Scouting Dossier"';

CREATE TABLE player_notes (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  player_id         CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  body              VARCHAR(4000) NOT NULL,
  visibility        ENUM('PRIVATE','ORGANIZATION') NOT NULL DEFAULT 'ORGANIZATION',
  author_id         CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  created_at        DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (id),
  KEY ix_pn_player (organization_id, player_id, created_at),
  CONSTRAINT fk_pnote_player FOREIGN KEY (player_id) REFERENCES players(id),
  CONSTRAINT fk_pnote_author FOREIGN KEY (organization_id, author_id) REFERENCES memberships(organization_id, user_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='08 sidebar "Notes & Tags"';

-- ===== 009_render_export_delivery.sql =====
-- Migration 009 — Export & Delivery (10): presets, render jobs + stages, report bundles, share links, deliveries, notifications
USE `otsi_owner_vie`;

CREATE TABLE export_presets (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  owner_organization_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  name              VARCHAR(80) NOT NULL COMMENT 'Output Preset select e.g. "Highlights Reel"',
  is_recommended    BOOLEAN NOT NULL DEFAULT FALSE COMMENT '"(Recommended)" suffix',
  helper_text       VARCHAR(200) NULL COMMENT '"Optimized for professional analysis and client sharing."',
  resolution        ENUM('720p','1080p','1440p','4K') NOT NULL,
  frame_rate        DECIMAL(6,3) NOT NULL,
  aspect_ratio      ENUM('16:9','9:16','1:1','4:5') NOT NULL,
  container         ENUM('MP4','MOV','WEBM') NOT NULL DEFAULT 'MP4',
  video_codec       ENUM('H264','H265','PRORES','VP9','AV1') NOT NULL DEFAULT 'H264',
  quality           ENUM('LOW','MEDIUM','HIGH','MAX') NOT NULL DEFAULT 'HIGH',
  owner_key         CHAR(36) CHARACTER SET ascii COLLATE ascii_bin AS (COALESCE(owner_organization_id, 'GLOBAL')) STORED,
  PRIMARY KEY (id),
  UNIQUE KEY uq_export_presets (owner_key, name),
  CONSTRAINT fk_xp_owner FOREIGN KEY (owner_organization_id) REFERENCES organizations(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE render_jobs (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  reel_id           CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  reel_revision_id  CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL COMMENT 'Exact saved timeline being rendered',
  job_kind          ENUM('FINAL','PREVIEW') NOT NULL DEFAULT 'FINAL' COMMENT 'Preview Render vs Generate/Export',
  preset_id         CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  resolution        ENUM('720p','1080p','1440p','4K') NOT NULL COMMENT 'Queue spec line "MP4 • 4K • 16:9 • 02:17"',
  width_px          SMALLINT UNSIGNED NOT NULL,
  height_px         SMALLINT UNSIGNED NOT NULL,
  frame_rate        DECIMAL(6,3) NOT NULL,
  aspect_ratio      ENUM('16:9','9:16','1:1','4:5') NOT NULL,
  container         ENUM('MP4','MOV','WEBM') NOT NULL,
  video_codec       ENUM('H264','H265','PRORES','VP9','AV1') NOT NULL,
  quality           ENUM('LOW','MEDIUM','HIGH','MAX') NOT NULL,
  include_branding  BOOLEAN NOT NULL DEFAULT TRUE,
  brand_kit_id      CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  overlay_logo      BOOLEAN NOT NULL DEFAULT TRUE,
  overlay_player_name_stats BOOLEAN NOT NULL DEFAULT TRUE,
  overlay_match_info_banner BOOLEAN NOT NULL DEFAULT TRUE,
  custom_intro_outro BOOLEAN NOT NULL DEFAULT TRUE,
  expected_duration_us BIGINT UNSIGNED NOT NULL,
  state             ENUM('QUEUED','RUNNING','SUCCEEDED','FAILED','CANCELLED','BLOCKED','REVIEW_REQUIRED') NOT NULL DEFAULT 'QUEUED',
  queue_position    INT UNSIGNED NULL,
  progress_pct      DECIMAL(5,2) NOT NULL DEFAULT 0,
  eta_seconds       INT UNSIGNED NULL COMMENT '"12 min remaining"',
  is_paused         BOOLEAN NOT NULL DEFAULT FALSE COMMENT 'Pause button',
  manifest_asset_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  output_asset_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  idempotency_key   VARCHAR(128) CHARACTER SET ascii NOT NULL,
  attempt_count     SMALLINT UNSIGNED NOT NULL DEFAULT 0,
  failure_code      VARCHAR(64) CHARACTER SET ascii NULL,
  requested_by      CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  created_at        DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  started_at        DATETIME(6) NULL,
  completed_at      DATETIME(6) NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_rj_org_id (organization_id, id),
  UNIQUE KEY uq_rj_idem (organization_id, idempotency_key),
  KEY ix_rj_queue (organization_id, state, queue_position, created_at),
  KEY ix_rj_reel (organization_id, reel_id, created_at),
  CONSTRAINT fk_rj_reel   FOREIGN KEY (organization_id, reel_id) REFERENCES reel_projects(organization_id, id),
  CONSTRAINT fk_rj_rev    FOREIGN KEY (organization_id, reel_revision_id) REFERENCES reel_revisions(organization_id, id),
  CONSTRAINT fk_rj_preset FOREIGN KEY (preset_id) REFERENCES export_presets(id),
  CONSTRAINT fk_rj_brand  FOREIGN KEY (organization_id, brand_kit_id) REFERENCES brand_kits(organization_id, id),
  CONSTRAINT fk_rj_man    FOREIGN KEY (organization_id, manifest_asset_id) REFERENCES assets(organization_id, id),
  CONSTRAINT fk_rj_out    FOREIGN KEY (organization_id, output_asset_id) REFERENCES assets(organization_id, id),
  CONSTRAINT fk_rj_user   FOREIGN KEY (requested_by) REFERENCES users(id),
  CONSTRAINT ck_rj_progress CHECK (progress_pct BETWEEN 0 AND 100),
  CONSTRAINT ck_rj_done   CHECK (state <> 'SUCCEEDED' OR (output_asset_id IS NOT NULL AND manifest_asset_id IS NOT NULL AND progress_pct = 100)),
  CONSTRAINT ck_rj_fps    CHECK (frame_rate > 0 AND frame_rate <= 120)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

-- 10 Render Progress strip: Preparing Files -> Rendering Video -> Processing Reports -> Finalizing.
CREATE TABLE render_job_stages (
  render_job_id     CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  stage             ENUM('PREPARING_FILES','RENDERING_VIDEO','PROCESSING_REPORTS','FINALIZING','QC') NOT NULL,
  ui_order          TINYINT UNSIGNED NOT NULL,
  status            ENUM('QUEUED','RUNNING','SUCCEEDED','FAILED','CANCELLED','BLOCKED','REVIEW_REQUIRED') NOT NULL DEFAULT 'QUEUED',
  progress_pct      DECIMAL(5,2) NOT NULL DEFAULT 0,
  started_at        DATETIME(6) NULL,
  completed_at      DATETIME(6) NULL,
  PRIMARY KEY (render_job_id, stage),
  CONSTRAINT fk_rjs_job FOREIGN KEY (organization_id, render_job_id) REFERENCES render_jobs(organization_id, id) ON DELETE CASCADE,
  CONSTRAINT ck_rjs_progress CHECK (progress_pct BETWEEN 0 AND 100)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE render_qc_checks (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  render_job_id     CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  check_kind        ENUM('FFPROBE_STREAMS','DURATION_MATCH','AV_SYNC','LOUDNESS','SPOTLIGHT_TARGET_ALIGNMENT','RIGHTS_DEPENDENCIES','BLACK_FRAMES') NOT NULL,
  passed            BOOLEAN NOT NULL,
  measurements      JSON NOT NULL DEFAULT (JSON_OBJECT()),
  checked_at        DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (id),
  UNIQUE KEY uq_rqc (render_job_id, check_kind),
  CONSTRAINT fk_rqc_job FOREIGN KEY (organization_id, render_job_id) REFERENCES render_jobs(organization_id, id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

-- 10 Output & Reports: per export, which deliverables to bundle.
CREATE TABLE export_bundles (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  render_job_id     CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  include_performance_report_pdf BOOLEAN NOT NULL DEFAULT TRUE,
  include_player_analysis_pdf BOOLEAN NOT NULL DEFAULT TRUE,
  include_event_list_csv BOOLEAN NOT NULL DEFAULT FALSE,
  include_heatmaps_png BOOLEAN NOT NULL DEFAULT FALSE,
  report_id         CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  status            ENUM('QUEUED','RUNNING','SUCCEEDED','FAILED','CANCELLED','BLOCKED','REVIEW_REQUIRED') NOT NULL DEFAULT 'QUEUED',
  created_at        DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (id),
  UNIQUE KEY uq_eb_org_id (organization_id, id),
  UNIQUE KEY uq_eb_job (render_job_id),
  CONSTRAINT fk_eb_job    FOREIGN KEY (organization_id, render_job_id) REFERENCES render_jobs(organization_id, id) ON DELETE CASCADE,
  CONSTRAINT fk_eb_report FOREIGN KEY (organization_id, report_id) REFERENCES reports(organization_id, id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE report_exports (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  report_id         CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  bundle_id         CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  export_kind       ENUM('PERFORMANCE_PDF','PLAYER_ANALYSIS_PDF','EVENT_LIST_CSV','HEATMAPS_PNG_ZIP','PLAYER_REPORT_PDF') NOT NULL,
  state             ENUM('QUEUED','RUNNING','SUCCEEDED','FAILED','CANCELLED','BLOCKED','REVIEW_REQUIRED') NOT NULL DEFAULT 'QUEUED',
  output_asset_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  idempotency_key   VARCHAR(128) CHARACTER SET ascii NOT NULL,
  requested_by      CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  created_at        DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  completed_at      DATETIME(6) NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_re_idem (organization_id, idempotency_key),
  KEY ix_re_report (organization_id, report_id, created_at),
  CONSTRAINT fk_re_report FOREIGN KEY (organization_id, report_id) REFERENCES reports(organization_id, id),
  CONSTRAINT fk_re_bundle FOREIGN KEY (organization_id, bundle_id) REFERENCES export_bundles(organization_id, id),
  CONSTRAINT fk_re_out    FOREIGN KEY (organization_id, output_asset_id) REFERENCES assets(organization_id, id),
  CONSTRAINT fk_re_user   FOREIGN KEY (requested_by) REFERENCES users(id),
  CONSTRAINT ck_re_src    CHECK (report_id IS NOT NULL OR bundle_id IS NOT NULL),
  CONSTRAINT ck_re_done   CHECK (state <> 'SUCCEEDED' OR output_asset_id IS NOT NULL)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='08 Export PDF, 10 bundle files, 09 report downloads';

CREATE TABLE share_links (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  library_item_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  asset_id          CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'Pinned file (NULL => latest primary asset of the item)',
  token_hash        CHAR(64) CHARACTER SET ascii NOT NULL COMMENT 'SHA-256 of random token; token shown once',
  public_slug       VARCHAR(64) CHARACTER SET ascii NOT NULL COMMENT 'URL path segment (non-guessable)',
  password_hash     VARCHAR(255) NULL COMMENT 'argon2id; Password Protection toggle',
  expires_at        DATETIME(6) NULL COMMENT 'Set Expiry Date toggle',
  can_download      BOOLEAN NOT NULL DEFAULT TRUE,
  can_comment       BOOLEAN NOT NULL DEFAULT TRUE,
  status            ENUM('PENDING_EXPORT','ACTIVE','REVOKED','EXPIRED') NOT NULL DEFAULT 'PENDING_EXPORT' COMMENT 'Pill "Not ready" / "Ready"',
  created_by        CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  created_at        DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  revoked_at        DATETIME(6) NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_sl_org_id (organization_id, id),
  UNIQUE KEY uq_sl_token (token_hash),
  UNIQUE KEY uq_sl_slug (public_slug),
  KEY ix_sl_item (organization_id, library_item_id, status),
  CONSTRAINT fk_sl_item  FOREIGN KEY (organization_id, library_item_id) REFERENCES library_items(organization_id, id),
  CONSTRAINT fk_sl_asset FOREIGN KEY (organization_id, asset_id) REFERENCES assets(organization_id, id),
  CONSTRAINT fk_sl_user  FOREIGN KEY (created_by) REFERENCES users(id),
  CONSTRAINT ck_sl_revoked CHECK (status <> 'REVOKED' OR revoked_at IS NOT NULL)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

ALTER TABLE comments ADD CONSTRAINT fk_comments_share FOREIGN KEY (organization_id, author_share_link_id) REFERENCES share_links(organization_id, id);

CREATE TABLE share_link_access (
  id                BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  share_link_id     CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  action            ENUM('OPEN','PLAY','DOWNLOAD','COMMENT','PASSWORD_FAIL') NOT NULL,
  decision          ENUM('ALLOW','DENY') NOT NULL,
  deny_reason       VARCHAR(64) CHARACTER SET ascii NULL,
  ip_hash           CHAR(64) CHARACTER SET ascii NULL,
  user_agent_hash   CHAR(64) CHARACTER SET ascii NULL,
  accessed_at       DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (id),
  KEY ix_sla_link (share_link_id, accessed_at),
  CONSTRAINT fk_sla_link FOREIGN KEY (share_link_id) REFERENCES share_links(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE deliveries (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  library_item_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  render_job_id     CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  share_link_id     CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  channel           ENUM('SIGNED_URL','EMAIL','INTERNAL','PORTAL') NOT NULL,
  message           VARCHAR(300) NULL COMMENT 'Team Collaboration textarea (counter "0/300")',
  notify_team_when_ready BOOLEAN NOT NULL DEFAULT TRUE,
  notify_client     BOOLEAN NOT NULL DEFAULT TRUE,
  state             ENUM('QUEUED','RUNNING','SUCCEEDED','FAILED','CANCELLED','BLOCKED','REVIEW_REQUIRED') NOT NULL DEFAULT 'QUEUED' COMMENT 'Ready for Delivery / Delivery not ready',
  rights_checked_at DATETIME(6) NULL,
  rights_decision_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  requested_by      CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  scheduled_for     DATETIME(6) NULL,
  delivered_at      DATETIME(6) NULL,
  failure_code      VARCHAR(64) CHARACTER SET ascii NULL,
  created_at        DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (id),
  UNIQUE KEY uq_del_org_id (organization_id, id),
  KEY ix_del_item (organization_id, library_item_id, created_at),
  CONSTRAINT fk_del_item  FOREIGN KEY (organization_id, library_item_id) REFERENCES library_items(organization_id, id),
  CONSTRAINT fk_del_job   FOREIGN KEY (organization_id, render_job_id) REFERENCES render_jobs(organization_id, id),
  CONSTRAINT fk_del_link  FOREIGN KEY (organization_id, share_link_id) REFERENCES share_links(organization_id, id),
  CONSTRAINT fk_del_user  FOREIGN KEY (requested_by) REFERENCES users(id),
  CONSTRAINT ck_del_done  CHECK (state <> 'SUCCEEDED' OR (delivered_at IS NOT NULL AND rights_checked_at IS NOT NULL))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE delivery_recipients (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  delivery_id       CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  recipient_kind    ENUM('TEAM_MEMBER','CLIENT') NOT NULL,
  user_id           CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  client_contact_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  status            ENUM('PENDING','SENT','OPENED','BOUNCED','FAILED') NOT NULL DEFAULT 'PENDING',
  sent_at           DATETIME(6) NULL,
  opened_at         DATETIME(6) NULL,
  PRIMARY KEY (id),
  KEY ix_dr_delivery (organization_id, delivery_id),
  CONSTRAINT fk_dr_delivery FOREIGN KEY (organization_id, delivery_id) REFERENCES deliveries(organization_id, id) ON DELETE CASCADE,
  CONSTRAINT fk_dr_user     FOREIGN KEY (organization_id, user_id) REFERENCES memberships(organization_id, user_id),
  CONSTRAINT ck_dr_target   CHECK ((recipient_kind = 'TEAM_MEMBER' AND user_id IS NOT NULL) OR (recipient_kind = 'CLIENT' AND client_contact_id IS NOT NULL))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE client_contacts (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  display_name      VARCHAR(120) NOT NULL,
  email             VARCHAR(320) NOT NULL,
  company           VARCHAR(150) NULL,
  consent_state     ENUM('UNKNOWN','GRANTED','WITHDRAWN') NOT NULL DEFAULT 'UNKNOWN',
  created_at        DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (id),
  UNIQUE KEY uq_cc_org_id (organization_id, id),
  UNIQUE KEY uq_cc_email (organization_id, email),
  CONSTRAINT fk_cc_org FOREIGN KEY (organization_id) REFERENCES organizations(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='"Notify client" / "Deliver to Client" / "Send to Client" recipients';

ALTER TABLE delivery_recipients ADD CONSTRAINT fk_dr_client FOREIGN KEY (organization_id, client_contact_id) REFERENCES client_contacts(organization_id, id);

-- ===== 010_commercial_governance_ops.sql =====
-- Migration 010 — Dashboard KPIs (01), billing/entitlements/quotas, policy & rights decisions, audit, outbox,
--                 idempotency, security, retention, release gates
USE `otsi_owner_vie`;

-- 01 Home KPI tiles (Matches Analyzed / Players Tracked / Reels Generated / Reports Created + trend).
-- Materialised by a scheduled job from domain tables; the API never computes these on the request path.
CREATE TABLE kpi_snapshots (
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  kpi_key           ENUM('MATCHES_ANALYZED','PLAYERS_TRACKED','REELS_GENERATED','REPORTS_CREATED') NOT NULL,
  period_kind       ENUM('ALL_TIME','LAST_30_DAYS','MONTH') NOT NULL,
  period_start      DATE NOT NULL,
  value_count       BIGINT UNSIGNED NOT NULL,
  previous_value    BIGINT UNSIGNED NULL,
  trend_pct         DECIMAL(7,2) AS (IF(previous_value IS NULL OR previous_value = 0, NULL, ROUND((value_count - previous_value) * 100 / previous_value, 2))) STORED,
  series            JSON NULL COMMENT 'Mini bar chart points (last 5 periods) — replaces decorative fixed bars',
  computed_at       DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (organization_id, kpi_key, period_kind, period_start),
  CONSTRAINT fk_kpi_org FOREIGN KEY (organization_id) REFERENCES organizations(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE plans (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  code              VARCHAR(40) CHARACTER SET ascii NOT NULL,
  name              VARCHAR(80) NOT NULL,
  active            BOOLEAN NOT NULL DEFAULT TRUE,
  created_at        DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (id),
  UNIQUE KEY uq_plans_code (code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE plan_versions (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  plan_id           CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  version           INT UNSIGNED NOT NULL,
  effective_at      DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  feature_limits    JSON NOT NULL COMMENT '{"analysis_minutes":600,"render_minutes":120,"storage_gb":500,"seats":5,"max_upload_bytes":...}',
  is_published      BOOLEAN NOT NULL DEFAULT FALSE,
  PRIMARY KEY (id),
  UNIQUE KEY uq_plan_versions (plan_id, version),
  CONSTRAINT fk_pv_plan FOREIGN KEY (plan_id) REFERENCES plans(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE plan_prices (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  plan_version_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  provider          ENUM('STRIPE','PADDLE','MANUAL') NOT NULL,
  external_price_id VARCHAR(255) CHARACTER SET ascii NOT NULL,
  billing_period    ENUM('MONTHLY','YEARLY','CUSTOM') NOT NULL,
  currency          CHAR(3) CHARACTER SET ascii NOT NULL,
  unit_amount_minor BIGINT UNSIGNED NOT NULL,
  created_at        DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (id),
  UNIQUE KEY uq_plan_prices_ext (provider, external_price_id),
  CONSTRAINT fk_pp_version FOREIGN KEY (plan_version_id) REFERENCES plan_versions(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE billing_customers (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  provider          ENUM('STRIPE','PADDLE','MANUAL') NOT NULL,
  provider_customer_id VARCHAR(255) CHARACTER SET ascii NOT NULL,
  created_at        DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (id),
  UNIQUE KEY uq_bc_org (organization_id),
  UNIQUE KEY uq_bc_ext (provider, provider_customer_id),
  CONSTRAINT fk_bc_org FOREIGN KEY (organization_id) REFERENCES organizations(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE subscriptions (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  organization_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  plan_version_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  provider_subscription_id VARCHAR(255) CHARACTER SET ascii NULL,
  state             ENUM('TRIALING','ACTIVE','PAST_DUE','CANCELED','UNPAID','INCOMPLETE') NOT NULL,
  period_start      DATETIME(6) NULL,
  period_end        DATETIME(6) NULL,
  trial_end         DATETIME(6) NULL,
  cancel_at_period_end BOOLEAN NOT NULL DEFAULT FALSE,
  row_version       BIGINT UNSIGNED NOT NULL DEFAULT 1,
  created_at        DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
  PRIMARY KEY (id),
  UNIQUE KEY uq_sub_ext (provider_subscription_id),
  KEY ix_sub_org (organization_id, state),
  CONSTRAINT fk_sub_org FOREIGN KEY (organization_id) REFERENCES organizations(id),
  CONSTRAINT fk_sub_pv  FOREIGN KEY (plan_version_id) REFERENCES plan_versions(id),
  CONSTRAINT ck_sub_period CHECK (period_end IS NULL OR period_start IS NULL OR period_end > period_start)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE billing_webhook_inbox (
  id                BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
